(() => {
  'use strict';
  const C=VersoCore,D=CURRICULUM,A=new VoiceAudio(),$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],E=C.esc;
  const icons={home:'M3 10 12 3l9 7M5 9v11h5v-6h4v6h5V9',route:'M5 4h5M5 4v5M5 4l5 5M19 20h-5M19 20v-5M19 20l-5-5M8 16l8-8',book:'M4 4h7a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4V4ZM14 7a3 3 0 0 1 3-3h3v15h-3a4 4 0 0 0-3 2',music:'M9 18V5l11-2v13M9 8l11-2M9 18c0 2-6 3-6 0s6-4 6 0ZM20 16c0 2-6 3-6 0s6-4 6 0Z',chart:'M4 20V10M10 20V4M16 20v-8M22 20H2',arrow:'M5 12h14M13 6l6 6-6 6',back:'M19 12H5M11 6l-6 6 6 6',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',play:'m8 5 11 7-11 7V5Z',pause:'M8 5v14M16 5v14',check:'m5 12 4 4L19 6',circle:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM12 7v5l3 2',lock:'M5 10h14v11H5V10ZM8 10V6a4 4 0 0 1 8 0v4',mic:'M9 4a3 3 0 0 1 6 0v8a3 3 0 0 1-6 0V4ZM5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8',tune:'M4 5h16M4 12h16M4 19h16M9 2v6M16 9v6M8 16v6',metro:'m12 2-8 19h16L12 2ZM7 17h10M12 17l6-10',help:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM9 9a3 3 0 0 1 6 0c0 2-3 2-3 5M12 17v.1',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',download:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',upload:'M12 16V4M7 9l5-5 5 5M4 16v5h16v-5',close:'m6 6 12 12M6 18 18 6',menu:'M4 6h16M4 12h16M4 18h16',headphones:'M4 14v-3a8 8 0 0 1 16 0v3M4 12h3v8H4a2 2 0 0 1-2-2v-4a2 2 0 0 1 2-2ZM20 12h-3v8h3a2 2 0 0 0 2-2v-4a2 2 0 0 0-2-2Z',leaf:'M20 3C8 2 2 8 5 15c3 7 15 3 15-12ZM4 21l11-12',save:'M4 3h14l3 3v15H3V3h1ZM7 3v6h10V3M7 21v-8h10v8',trash:'M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7',pen:'m4 16-1 5 5-1L20 8l-4-4L4 16ZM14 6l4 4',ear:'M7 9a5 5 0 0 1 10 0c0 4-4 4-4 8a3 3 0 0 1-6 0M10 9a2 2 0 0 1 4 0c0 2-2 2-2 4',award:'M17 9a5 5 0 1 1-10 0 5 5 0 0 1 10 0ZM8 13l-2 9 6-3 6 3-2-9',volume:'M3 9h4l5-5v16l-5-5H3V9ZM16 8a6 6 0 0 1 0 8M19 5a10 10 0 0 1 0 14'};
  const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.circle}"/></svg>`;
  const btn=(label,action,arg='',cls='',ic='')=>`<button type="button" class="btn ${cls}" data-action="${action}" data-arg="${E(arg)}">${ic?icon(ic,15):''}${label}</button>`;
  const actionLink=(label,action,arg='',ic='arrow')=>`<button class="text-link" type="button" data-action="${action}" data-arg="${E(arg)}">${label}${icon(ic,13)}</button>`;
  let storageWarning='',state;
  try{const raw=localStorage.getItem('verso-canto-v1');state=raw?C.validateState(JSON.parse(raw)):C.fresh();}catch{state=C.fresh();storageWarning='No se pudo recuperar el progreso. Conserva una copia e impórtala desde Ajustes si la tienes.';}
  const ui={view:'home',id:1,lessonTab:'learn',practiceTab:'tools',expanded:1,search:'',quizResults:{},examResults:{},papers:{},bar:0,voice:'melody',analysis:false,tempo:60,beats:4,metro:false,ear:null,earScore:[0,0],earResult:null,mediaUrls:[],render:0,assessment:null,recording:null,timer:{running:false,goal:20,elapsed:0,start:0,logged:0},busy:false};
  let toastTimer;
  function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),5500);}
  function save(){try{localStorage.setItem('verso-canto-v1',JSON.stringify(state));if(storageWarning.startsWith('No hay espacio'))storageWarning='';return true;}catch{storageWarning='No hay espacio o el navegador bloquea el almacenamiento. Exporta una copia antes de cerrar.';toast(storageWarning);return false;}}
  const lessonRecord=id=>state.lessons[id]||(state.lessons[id]={checks:[false,false,false]});
  const examRecord=id=>state.exams[id]||(state.exams[id]={});
  const completed=()=>D.lessons.filter(l=>C.lessonDone(state,l.id)).length;
  const nextLesson=()=>D.lessons.find(l=>!C.lessonDone(state,l.id)&&C.unlocked(state,l,D.lessons))||D.lessons.find(l=>!C.lessonDone(state,l.id))||D.lessons[47];
  const totalMinutes=()=>Math.round(Object.values(state.practice).reduce((a,b)=>a+b,0));
  const todayMinutes=()=>Math.round(state.practice[C.dateKey()]||0);
  const countLevel=id=>D.lessons.filter(l=>l.level===id&&C.lessonDone(state,l.id)).length;
  const levelOpen=id=>id===1||C.examPassed(state,id-1);
  function go(path){const hash='#/'+path;if(location.hash===hash)route();else location.hash=hash;}
  function stopAssessment(){ui.assessment=null;A.stopMic();clearInterval(ui.countTimer);ui.countTimer=null;clearTimeout(ui.assessmentTimeout);}
  function leaveView(){stopAssessment();A.stopSounds();ui.metro=false;ui.tuning=false;ui.busy=false;if(ui.recording)stopRecording();for(const url of ui.mediaUrls)URL.revokeObjectURL(url);ui.mediaUrls=[];}
  function route(){leaveView();const bits=location.hash.replace(/^#\/?/,'').split('/'),allowed=['home','route','lesson','exam','practice','compose','progress','method'];ui.view=allowed.includes(bits[0])?bits[0]:'home';ui.id=Math.max(1,Math.min(ui.view==='exam'?8:48,Number(bits[1])||1));if(ui.view==='route'&&bits[1])ui.expanded=Math.max(1,Math.min(8,Number(bits[1])||1));if(ui.view==='practice')ui.practiceTab=['tools','ear','repertoire','journal'].includes(bits[1])?bits[1]:'tools';ui.search='';render();window.scrollTo({top:0,behavior:'instant'});$('#main')?.focus({preventScroll:true});}
  const footer=()=>`<footer class="footer"><span>verso · Aprender. Escuchar. Crear.</span><button type="button" data-action="method">Método, privacidad y fuentes ${icon('arrow',11)}</button></footer>`;
  function shell(content){const active=ui.view==='lesson'||ui.view==='exam'?'route':ui.view;const names={home:'Mi aula',route:'Ruta de aprendizaje',practice:'Laboratorio vocal',compose:'Taller de canciones',progress:'Mi progreso',method:'La escuela'};return `<div class="shell"><aside class="sidebar" id="sidebar"><a href="#/home" class="brand" aria-label="Verso, inicio"><img src="assets/mark.svg" alt=""><span class="brand-word">verso</span></a><div class="brand-sub">CANTO Y COMPOSICIÓN</div><div class="nav-label">TU ESPACIO DE ESTUDIO</div><nav class="nav" aria-label="Navegación principal">${[['home','home','Mi aula'],['route','route','Ruta de aprendizaje'],['practice','music','Laboratorio vocal'],['compose','pen','Taller de canciones'],['progress','chart','Mi progreso']].map(([path,ic,label])=>`<a href="#/${path}" class="${active===path?'active':''}" ${active===path?'aria-current="page"':''}>${icon(ic,17)}${label}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note"><div class="note-icon">𝄞</div><h3>Tu voz, tu historia.</h3><p>Un poco de práctica consciente.<br>Un paso más, cada día.</p></div><button class="sidebar-link" data-action="method">${icon('help',16)}Cómo funciona Verso</button><button class="sidebar-link" data-action="settings">${icon('settings',16)}Ajustes y copias de seguridad</button><div class="local-status"><i class="dot"></i> Progreso guardado en este dispositivo</div></div></aside><div class="main-shell"><header class="topbar"><div class="row gap-sm"><button class="mobile-menu" data-action="menu" aria-label="Abrir o cerrar navegación">${icon('menu',20)}</button><div class="breadcrumbs">MI ESCUELA <span>/</span><strong>${E(names[active]||'MI AULA').toUpperCase()}</strong></div></div><div class="top-right"><button class="instrument-picker" data-action="settings" aria-label="Ajustar referencia vocal">Ref. ${E(C.noteName(state.settings.base,true))} ${icon('down',12)}</button><button class="text-link" data-action="method">${icon('help',16)}</button><button class="avatar" data-action="settings" aria-label="Ajustes personales">TÚ</button></div></header>${storageWarning?`<div class="storage-alert" role="alert">${E(storageWarning)}</div>`:''}<main class="main" id="main" tabindex="-1">${content}${footer()}</main></div></div>`;}
  function render(){for(const a of $$('audio')){if(a.pause)a.pause();}for(const url of ui.mediaUrls)URL.revokeObjectURL(url);ui.mediaUrls=[];ui.render++;let content;switch(ui.view){case'route':content=routePage();break;case'lesson':content=lessonPage();break;case'exam':content=examPage();break;case'practice':content=practicePage();break;case'compose':content=composePage();break;case'progress':content=progressPage();break;case'method':content=methodPage();break;default:content=homePage();}$('#app').innerHTML=shell(content);if(ui.view==='exam')loadEvidence(ui.id);if(ui.timer.running)updateTimerDisplay();}
  const voiceSeq=pattern=>C.reference(pattern,state.settings);
  function analysisCard(a){return `<section class="card"><div class="eyebrow">REVISIÓN DE MATERIAL</div><h3>Una estructura para escuchar.</h3><ul class="checklist">${[[a.lyricOK,'Letra, gancho e intención'],[a.melodyOK,'Ocho compases y 16 notas'],[a.songOK,'Canción de 16 compases'],[a.revisionOK,'Oyentes y revisión'],[a.finalOK,'Defensa y plan final']].map(([ok,label])=>`<li class="${ok?'ok':''}">${icon(ok?'check':'circle',14)}<span>${label}</span></li>`).join('')}</ul>${a.errors.length?`<ul class="analysis-list">${a.errors.slice(0,5).map(x=>`<li>${E(x)}</li>`).join('')}</ul>`:''}<p class="small muted mt">${a.notes} notas · ${a.words} palabras de defensa. No es una nota de calidad ni un pronóstico comercial.</p><ul class="analysis-list">${a.warnings.map(x=>`<li>${E(x)}</li>`).join('')}</ul></section>`;}
  function homePage(){const n=nextLesson(),c=completed(),pending=D.levels.find(x=>countLevel(x.id)===6&&!C.examPassed(state,x.id)),all=c===48&&C.examPassed(state,8);return `<header class="page-head home-head"><div><div class="eyebrow">CANTO · LETRA · MÚSICA</div><h1>Tu voz tiene algo<br>que contar.</h1><p>De una primera nota a una canción que puedas defender.</p></div><div class="home-seal"><span>UN CAMINO DE AUTOR</span><b>♫</b><span>ESCUCHAR · CREAR</span></div></header><section class="hero"><div class="hero-content"><div class="hero-kicker"><span class="eyebrow">${pending?'TU SIGUIENTE RETO':'TU PRÓXIMA CLASE'}</span><span class="pill white">${E(D.levels[n.level-1].tag)}</span></div><h2>${all?'Tu próxima canción<br>empieza aquí.':pending?'Escucha cuánto<br>has construido.':c?E(n.title):'Encuentra tu voz.<br>Escribe tu historia.'}</h2><p>${pending?'Reúne voz, comprensión y material propio en tu control de nivel.':E(n.subtitle)+' Escucha, prueba y vuelve a escribir.'}</p>${btn(all?'Ver mi recorrido':pending?'Presentar control':c?'Continuar mi aprendizaje':'Comenzar mi primera clase',all?'go':pending?'exam':'start',all?'progress':pending?pending.id:n.id,'','arrow')}<div class="hero-meta"><span>${icon('clock',12)} ${n.minutes} min con pausas, escucha y escritura</span><span>${icon('mic',12)} Tu voz real</span></div></div><div class="hero-art"><img src="assets/voice.svg" alt="Ilustración original de un micrófono y un cuaderno de canciones"><span class="hero-count">${String(n.id).padStart(2,'0')} / 48</span></div></section><section class="stats"><div class="stat"><div class="stat-icon">${icon('book',19)}</div><div><div class="stat-number">${c}<span>/ 48</span></div><div class="stat-label">Clases completadas</div></div></div><div class="stat"><div class="stat-icon">${icon('pen',19)}</div><div><div class="stat-number">08<span>niveles</span></div><div class="stat-label">Voz y creación, paso a paso</div></div></div><div class="stat"><div class="stat-icon">${icon('clock',19)}</div><div><div class="stat-number">${totalMinutes()}<span>min</span></div><div class="stat-label">Estudio registrado</div></div></div></section><div class="home-bottom"><section><div class="section-head"><h2>Un camino para hacerla tuya.</h2>${actionLink('Explorar la ruta','go','route')}</div><div class="level-grid">${D.levels.slice(0,3).map(levelMini).join('')}</div><div class="note mt-lg">Aprende a escribir canciones con identidad, claridad y recursos de comunicación. El éxito comercial también depende de factores externos; no se predice con una puntuación.</div></section><aside class="goal-card"><div class="eyebrow">TU ZONA DE TRABAJO</div><h3>${state.settings.confirmed?E(C.noteName(state.settings.low,true)+' – '+C.noteName(state.settings.high,true)):'Primero, una zona cómoda.'}</h3><p class="mt">Referencia: ${E(C.noteName(state.settings.base,true))}. Ajusta antes de cantar; no es una clasificación ni una meta de extensión.</p>${btn('Ajustar mi referencia','settings','','secondary w-full mt','tune')}<div class="rule"></div><h3>Una idea puede empezar hoy.</h3><p class="mt">Escribe una escena, prueba un gancho y escucha lo que cambia.</p>${btn('Abrir mi canción','go','compose','','pen')}</aside></div>`;}
  function levelMini(l){const open=levelOpen(l.id),done=C.examPassed(state,l.id),n=countLevel(l.id);return `<button class="level-mini" data-action="level" data-arg="${l.id}"><div class="row"><span class="mini-num">0${l.id}</span>${icon(done?'check':open?'arrow':'lock',15)}</div><div class="eyebrow">${E(l.tag)}</div><h3>${E(l.name)}</h3><p>6 clases · ${open?'Nivel disponible':'Vista previa disponible'}</p><div class="progress-line"><span style="width:${n/6*100}%"></span></div></button>`;}
  function routePage(){return `<header class="page-head"><div><div class="eyebrow">EL CAMINO COMPLETO</div><h1>Una voz. Ocho etapas.</h1><p>Explora todas las clases. Aprueba cada una y su control de nivel para habilitar la siguiente etapa.</p></div><label class="search">${icon('book',15)}<input type="search" id="lesson-search" placeholder="Buscar una clase…" aria-label="Buscar clases" value="${E(ui.search)}"></label></header><div id="route-levels">${routeLevels()}</div><div class="note">${icon('help',15)} Las clases se pueden leer en vista previa. El avance exige comprensión, voz, escritura y evidencias; el nivel preuniversitario es una preparación, sin equivalencia ni acreditación oficial.</div>`;}
  function routeLevels(){let found=0;const out=D.levels.map(l=>{const lessons=D.lessons.filter(x=>x.level===l.id&&(!ui.search||(x.title+' '+x.subtitle+' '+x.text).toLowerCase().includes(ui.search.toLowerCase())));if(!lessons.length)return '';found+=lessons.length;const expanded=ui.expanded===l.id||!!ui.search,open=levelOpen(l.id),done=C.examPassed(state,l.id),n=countLevel(l.id);return `<section class="level-block"><button class="level-header" data-action="expand" data-arg="${l.id}" aria-expanded="${expanded}"><span class="level-no ${l.color}">0${l.id}</span><span class="level-title"><span class="eyebrow">${E(l.tag)}</span><h2>${E(l.name)}</h2><p>${E(l.description)}</p></span><span class="level-side"><span class="pill ${done?'success':open?'':'locked'}">${done?'Nivel completado':open?'En tu camino':'Vista previa'}</span><span class="progress-line"><span style="width:${n/6*100}%"></span></span><span class="small muted">${n} de 6 clases</span></span>${icon(expanded?'down':'chevron',17)}</button>${expanded?`<div class="lesson-list">${lessons.map(x=>{const isDone=C.lessonDone(state,x.id),isOpen=C.unlocked(state,x,D.lessons);return `<button class="lesson-item" data-action="lesson" data-arg="${x.id}"><span class="lesson-status ${isDone?'done':isOpen?'current':''}">${isDone?icon('check',13):isOpen?icon('play',12):icon('lock',12)}</span><span><h3>${String(x.id).padStart(2,'0')} · ${E(x.title)}</h3><p>${E(x.subtitle)}</p></span><span class="duration">${x.minutes} min</span>${icon('chevron',13)}</button>`;}).join('')}<div class="level-exam row between"><span class="small muted">${icon('award',15)} Control de nivel 0${l.id}</span>${btn(done?'Ver mi evaluación':'Presentar evaluación','exam',l.id,'secondary sm',done?'check':'arrow')}</div></div>`:''}</section>`;}).join('');return found?out:'<div class="empty">No encontramos una clase con esas palabras. Prueba con “lectura”, “acordes” o “composición”.</div>';}
  function lessonPage(){const l=D.lessons[ui.id-1],level=D.levels[l.level-1],r=lessonRecord(l.id),open=C.unlocked(state,l,D.lessons),done=C.lessonDone(state,l.id),seq=voiceSeq(l.sequence);return `<header class="page-head lesson-head"><div><div class="eyebrow">NIVEL ${l.level} / CLASE ${l.id} DE 48</div><h1>${E(l.title)}</h1><p>${E(l.subtitle)}</p></div><span class="pill ${done?'success':open?'':'locked'}">${done?'Completada':open?l.minutes+' min de estudio':'Vista previa'}</span></header>${!open?'<div class="note warn mb">Puedes leer y explorar. Para evaluarte, completa el paso y control anteriores.</div>':''}<div class="tabs" role="tablist" aria-label="Secciones de la clase">${[['learn','Comprender'],['practice','Practicar'],['evaluate','Comprobar']].map(([id,label])=>`<button role="tab" aria-selected="${ui.lessonTab===id}" class="tab ${ui.lessonTab===id?'active':''}" data-action="lesson-tab" data-arg="${id}">${label}</button>`).join('')}</div><div class="lesson-layout"><article>${ui.lessonTab==='learn'?`<section class="card"><div class="eyebrow">ENTENDER PARA DECIDIR</div><div class="lesson-text">${l.text.split('\n\n').map(p=>`<p>${E(p)}</p>`).join('')}</div><div class="note mt-lg">${E(l.watch)}</div>${btn('Llevarlo a la práctica','lesson-tab','practice','mt-lg','arrow')}</section>`:ui.lessonTab==='practice'?`<section class="card"><div class="eyebrow">VOZ, OÍDO Y MATERIAL PROPIO</div><h2>Del intento a una decisión.</h2><ol class="step-list">${l.steps.map(s=>`<li>${E(s)}</li>`).join('')}</ol><div class="note">El patrón breve comprueba una muestra de alturas. La tarea creativa y su calidad necesitan escritura, canto y revisión.</div></section><div class="spaced">${exerciseSheet(seq,l.title,level.tempo)}</div><section class="card spaced"><h3>Tu ejercicio de autor.</h3><p class="mt">${E(l.assignment.prompt)}</p>${btn('Abrir mi canción','go','compose','secondary mt','pen')}</section>${btn('Comprobar y guardar mi ejercicio','lesson-tab','evaluate','mt-lg','arrow')}`:`<section class="card"><div class="eyebrow">COMPRENSIÓN</div><h2>Decisiones que puedes explicar.</h2>${quizForm(l.quiz,'lesson',l.id,open,ui.quizResults[l.id])}</section><section class="card spaced"><div class="eyebrow">CUADERNO DE CLASE</div><h2>Crea algo que podamos revisar.</h2><p class="mt">${E(l.assignment.prompt)}</p><form data-form="work" data-id="${l.id}"><label class="field mt"><span>Tu entrega · mínimo ${l.assignment.min} caracteres</span><textarea name="work" minlength="${l.assignment.min}" maxlength="5000" required ${!open?'disabled':''}>${E(r.work||'')}</textarea></label><p class="small muted mt">Se comprueba presencia de material; su calidad se valora con escucha y docente.</p><button type="submit" class="btn mt" ${!open?'disabled':''}>${icon('save',14)}Guardar mi ejercicio</button></form></section><section class="card spaced"><h2>Escucha y revisa.</h2>${l.checks.map((x,i)=>`<label class="check"><input type="checkbox" data-change="lesson-check" data-id="${l.id}" data-index="${i}" ${r.checks?.[i]?'checked':''} ${!open?'disabled':''}>${E(x)}</label>`).join('')}</section>`}</article><aside class="lesson-aside"><div class="session-card"><div class="eyebrow">TU SESIÓN</div><h3>Una evidencia por paso.</h3>${statusRow('Comprensión 3/3',r.quiz===3)}${statusRow('Secuencia vocal',r.practical)}${statusRow('Ejercicio propio',(r.work||'').trim().length>=l.assignment.min)}${statusRow('Autoobservación',r.checks?.length===3&&r.checks.every(Boolean))}${btn(done?'Clase completada':'Completar esta clase','complete-lesson',l.id,'w-full mt',done?'check':'arrow')}</div><div class="spaced">${assessmentPanel('lesson',l.id,seq,level,open)}</div></aside></div><div class="lesson-nav">${l.id>1?btn('Clase anterior','lesson',l.id-1,'secondary','back'):'<span></span>'}${l.id%6===0?btn('Control de nivel','exam',l.level,'secondary','award'):btn('Siguiente clase','lesson',l.id+1,'secondary','arrow')}</div>`;}
  function statusRow(label,ok){return `<div class="status-row ${ok?'ok':''}"><span class="state-icon">${icon(ok?'check':'circle',15)}</span>${E(label)}<span class="pill ${ok?'success':''}">${ok?'Hecho':'Pendiente'}</span></div>`;}
  function exerciseSheet(seq,title,tempo){return `<div class="sheet"><div class="sheet-header"><h3>${E(title)}</h3>${btn('Escuchar','play-sequence',seq.join(',')+'|'+tempo,'secondary sm','play')}</div><div class="score-scroll">${C.scoreSvg(seq,{title})}</div><div class="sheet-footer">Altura de concierto · ♩ = ${tempo} · Referencias de estudio sintetizadas</div><div class="tab-notes">${seq.map(m=>`<div class="note-chip">${E(C.noteName(m,true))}</div>`).join('')}</div></div>`;}
  function fingerboard(seq=[]){const notes=seq.length?[...new Set(seq)]:Array.from({length:18},(_,i)=>Math.max(36,state.settings.base-5)+i);return `<div class="voice-keyboard">${notes.filter(C.inRange).map(m=>`<button class="voice-key ${[1,3,6,8,10].includes(m%12)?'black':''} ${m<state.settings.low||m>state.settings.high?'outside':''}" data-action="note" data-arg="${m}" aria-label="Escuchar ${E(C.noteName(m,true))}"><span>${E(C.noteName(m,true))}</span></button>`).join('')}</div><p class="small muted mt">Teclado de referencia, sin evaluación. Las notas fuera de tu zona declarada aparecen atenuadas; no necesitas cantarlas.</p>`;}
  function quizForm(questions,type,id,open,result){return `<form data-form="quiz" data-kind="${type}" data-id="${id}">${questions.map((q,i)=>`<fieldset class="question"><legend>${i+1}. ${E(q.q)}</legend>${q.options.map((option,j)=>`<label><input type="radio" name="q${i}" value="${j}" required ${!open?'disabled':''} ${result?.answers?.[i]===j?'checked':''}>${E(option)}</label>`).join('')}${result?`<div class="feedback ${result.answers[i]===q.answer?'':'wrong'}">${result.answers[i]===q.answer?'Correcto. ':'Revisa esta idea: '}${E(q.why)}</div>`:''}</fieldset>`).join('')}${result?`<div class="note ${result.score===(type==='lesson'?3:100)?'success':'warn'}">${type==='lesson'?result.score+' de 3 respuestas correctas. Necesitas las tres.':result.score+' / 100. Se aprueba con 80.'}</div>`:''}<button type="submit" class="btn mt" ${!open?'disabled':''}>${result?'Repetir comprobación':'Comprobar respuestas'} ${icon('arrow',15)}</button></form>`;}
  function wave(){return `<div class="wave" id="live-wave">${Array.from({length:17},(_,i)=>`<i style="--h:${7+Math.sin(i*.8)**2*25}px;--d:${i*.08}s"></i>`).join('')}</div>`;}
  function assessmentPanel(type,id,sequence,level,open){const r=type==='lesson'?state.lessons[id]:state.exams[id],done=r?.practical,fit=C.fits(sequence,state.settings);return `<section class="practice-live"><div class="live-kicker">${type==='exam'?'VOZ Y REGULARIDAD':'CANTA CON TU VOZ'}</div><div class="live-target" id="live-target">${E(C.noteName(sequence[0],true))}<small id="live-location">Referencia ajustable · altura real</small></div>${wave()}<div class="live-note" id="live-note">${done?'Aprobada'+(r.reference?' con referencia '+C.noteName(r.reference,true):''):'Micrófono apagado'}</div><div class="live-meter"><div id="live-meter"></div></div><div class="live-hint" id="live-hint">${sequence.length} notas · ±${level.cents} cents${type==='exam'?' · '+level.tempo+' BPM':' · sin tempo exigido'}<br>Sonido recto y cómodo. Separa notas repetidas.</div>${!fit?'<div class="note warn mt">Confirma una referencia y una zona cómoda en Ajustes. Si este patrón no cabe, consulta a tu docente antes de intentarlo.</div>':''}<button type="button" id="assessment-start" class="btn w-full mt" data-action="assessment" data-arg="${type}:${id}" ${!open||!fit?'disabled':''}>${icon('mic',13)}${done?'Volver a practicar':'Activar y cantar'}</button>${actionLink('Ajustar mi referencia','settings','','tune')}<div class="small muted mt">Análisis local. No graba ni verifica técnica, salud o identidad.</div><div class="tab-notes" style="justify-content:center;padding:14px 0;gap:4px">${sequence.map((_,i)=>`<span id="seq-${i}" style="height:5px;width:9px;border-radius:2px;background:#ced9c0"></span>`).join('')}</div><div id="visual-beat" class="test-progress mt"></div></section>`;}
  function paper(id){if(!ui.papers[id]){const pool=D.lessons.filter(l=>l.level===id).flatMap(l=>l.quiz);for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}ui.papers[id]=pool.slice(0,10);}return ui.papers[id];}
  function examPage(){const l=D.levels[ui.id-1],e=examRecord(l.id),open=C.examReady(state,l.id,D.lessons),done=C.examPassed(state,l.id),req=C.examRequirements(state,l,D.lessons),tab=ui.examTab||'summary',seq=voiceSeq(l.exam);return `<header class="page-head"><div><div class="eyebrow">CONTROL DE NIVEL ${l.id} · ${E(l.tag)}</div><h1>${E(l.name)}.<br>Haz audible tu avance.</h1><p>${E(l.deliverable)}</p></div><span class="pill ${done?'success':open?'':'locked'}">${done?'Completado':open?'Disponible':'Completa las seis clases'}</span></header><div class="tabs" role="tablist" aria-label="Secciones del control">${[['summary','Tu evaluación'],['theory','Teoría'],['instrument','Voz'],['portfolio','Portafolio']].map(([id,label])=>`<button class="tab ${tab===id?'active':''}" role="tab" aria-selected="${tab===id}" data-action="exam-tab" data-arg="${id}">${label}</button>`).join('')}</div><div class="exam-layout"><article>${tab==='summary'?`<section class="card"><h2>Comprensión, ejecución y obra propia.</h2><ol class="step-list"><li>Seis clases con preguntas, secuencia vocal, cuaderno de clase y observación.</li><li>Diez preguntas de nivel: necesitas ocho respuestas correctas.</li><li>Patrón vocal a ${l.tempo} BPM y ±${l.cents} cents. Al menos 70% de intervalos entre ataques dentro de ±${l.id<3?35:30}% del pulso.</li><li>Una toma de ${l.record} segundos o más; admite pausas y explicaciones breves. ${l.id<3?'Añade autoobservación.':'Revisión docente de 16/20, sin criterios inferiores a 3.'}</li><li>${E(l.deliverable)}</li></ol><div class="note warn">El detector no certifica técnica, salud, origen de la voz ni calidad de la canción. La rúbrica es declarada y local; no acredita un título ni predice éxito.</div>${btn('Empezar con teoría','exam-tab','theory','mt-lg','arrow')}</section>`:tab==='theory'?`<section class="card"><div class="eyebrow">TEORÍA · ${e.theory||0}/100 GUARDADO</div><h2>Entender lo que eliges.</h2>${quizForm(paper(l.id),'exam',l.id,open,ui.examResults[l.id])}</section>`:tab==='instrument'?`<section class="card"><h2>Una altura por pulso.</h2><p class="mt">Escucha primero y confirma la zona cómoda. Tras cuatro pulsos de preparación, sigue el pulso visual. El primer ataque establece la referencia temporal; se miden los intervalos posteriores.</p><div class="note mt">La prueba apaga referencias y metrónomo sonoro. Usa sonido recto y separa notas repetidas. Detén el ejercicio si necesitas descansar.</div></section><div class="spaced">${exerciseSheet(seq,'Secuencia del nivel '+l.id,l.tempo)}</div><div class="spaced">${assessmentPanel('exam',l.id,seq,l,open)}</div>`:portfolioPanel(l,e,open)}</article><aside class="lesson-aside"><div class="session-card"><div class="eyebrow">REQUISITOS</div><h3>Tu evidencia, reunida.</h3><ul class="checklist">${req.map(r=>`<li class="${r.ok?'ok':''}">${icon(r.ok?'check':'circle',15)}<span>${E(r.label)}</span></li>`).join('')}</ul>${btn(done?'Nivel completado':'Completar nivel y avanzar','complete-exam',l.id,'w-full mt','arrow')}${l.id>=3?btn('Abrir mi canción','go','compose','secondary w-full mt','pen'):''}</div></aside></div>`;}
  function portfolioPanel(l,e,open){return `<section class="card"><div class="eyebrow">TU VOZ Y TU MATERIAL</div><h2>Escúchate con atención.</h2><p class="mt">${E(l.deliverable)}</p><div class="note mt">La toma se guarda localmente. Descárgala: la copia de progreso no incluye audio. Puede contener pausas, frases y explicación breve; la app no comprueba su contenido ni procedencia.</div><div class="row between wrap mt-lg"><span id="record-status" class="small muted">${e.evidence?'Guardada · '+Math.round(e.evidence.duration)+' s':'Mínimo '+l.record+' s · máximo 5 minutos'}</span><button class="btn" id="record-button" data-action="record" data-arg="${l.id}" ${!open?'disabled':''}>${icon('mic',14)}Grabar mi muestra</button></div><div id="evidence-player" class="mt">${e.evidence?'<p class="small muted">Cargando la toma local…</p>':''}</div><label class="field mt"><span>Aportar una grabación propia · hasta 20 MB</span><input type="file" id="audio-import" accept="audio/*" data-level="${l.id}" ${!open?'disabled':''}></label><p class="small muted mt">Importar audio no sustituye el control con micrófono. La voz grabada y la guía de acordes son recursos separados, sin mezcla automática.</p></section><section class="card spaced"><div class="eyebrow">${l.id<3?'AUTOOBSERVACIÓN':'REVISIÓN DOCENTE DECLARADA'}</div><h2>Una escucha con criterio.</h2><ul class="step-list">${l.rubric.map(x=>`<li>${E(x)}</li>`).join('')}</ul>${l.id<3?`<label class="check"><input type="checkbox" data-change="self-review" data-id="${l.id}" ${e.selfReview?'checked':''} ${!open?'disabled':''}>He escuchado mi muestra y revisado estos criterios.</label>`:`<div class="note">Pide revisión de voz y material completo. Este registro no verifica identidad ni envía automáticamente archivos al docente.</div><form data-form="review" data-id="${l.id}" class="mt"><label class="field"><span>Docente o revisor</span><input name="reviewer" required minlength="3" maxlength="120" value="${E(e.review?.name||'')}" ${!open?'disabled':''}></label><table class="review-table mt"><caption class="small muted">0: sin evidencia · 3: suficiente · 4: sólido · 5: consistente</caption><tbody>${l.rubric.map((x,i)=>`<tr><td>${E(x)}</td><td><select name="r${i}" aria-label="Puntuación ${E(x)}" ${!open?'disabled':''}>${[0,1,2,3,4,5].map(n=>`<option value="${n}" ${e.review?.scores?.[i]===n?'selected':''}>${n}/5</option>`).join('')}</select></td></tr>`).join('')}</tbody></table><label class="field mt"><span>Observaciones y próxima prioridad · mínimo 30 caracteres</span><textarea name="feedback" required minlength="30" maxlength="3000" ${!open?'disabled':''}>${E(e.review?.feedback||'')}</textarea></label><button class="btn mt" type="submit" ${!open?'disabled':''}>Guardar revisión</button></form>`}</section>${l.id>=3?`<section class="card spaced"><h2>Tu canción en desarrollo.</h2><p class="mt">Completa los requisitos creativos indicados a la derecha en el taller. El análisis verifica estructura y presencia de evidencias; la calidad se revisa cantando y con docente.</p>${btn('Abrir mi canción','go','compose','mt secondary','pen')}</section>`:''}`;}
  function practicePage(){return `<header class="page-head"><div><div class="eyebrow">PREPARA, ESCUCHA, REPITE</div><h1>El lugar donde sucede.</h1><p>Escucha, encuentra el pulso y canta en una zona cómoda.</p></div><span class="pill">${icon('clock',12)} ${todayMinutes()} min hoy</span></header><div class="tabs" role="tablist" aria-label="Espacios de práctica">${[['tools','Herramientas','tune'],['ear','Entrenar el oído','ear'],['repertoire','Estudios originales','book'],['journal','Mi sesión','clock']].map(([id,label,ic])=>`<button class="tab ${ui.practiceTab===id?'active':''}" role="tab" aria-selected="${ui.practiceTab===id}" data-action="practice-tab" data-arg="${id}">${icon(ic,14)}${label}</button>`).join('')}</div>${ui.practiceTab==='tools'?toolsPanel():ui.practiceTab==='ear'?earPanel():ui.practiceTab==='repertoire'?repertoirePanel():sessionPanel()}`;}
  function scaleLab(){return '';}
  function toolsPanel(){return `<div class="practice-grid"><section class="card tuner"><div class="eyebrow">REFERENCIA Y AFINACIÓN</div><h2>Escucha tu centro.</h2><p class="small mt">Zona declarada: ${E(C.noteName(state.settings.low,true))} – ${E(C.noteName(state.settings.high,true))}</p><div class="tuner-note" id="tuner-note">—<small></small></div><div class="tuner-hz" id="tuner-hz">Altura de concierto · La4 = ${state.settings.a} Hz</div><div class="tuner-gauge"><span>−50</span><span>BAJO</span><span>0</span><span>ALTO</span><span>+50</span><i class="tuner-needle" id="tuner-needle"></i></div><div class="tuner-cents" id="tuner-cents">Una nota recta y cómoda, sin perseguir la pantalla.</div><button id="tuner-button" data-action="tuner" class="btn">${icon('mic',14)}Activar escucha</button>${btn('Ajustar mi referencia','settings','','secondary mt','tune')}<p class="small muted mt">La lectura no evalúa salud, esfuerzo ni técnica. Alterna escucha y comprobación con pausas.</p></section><section class="card center"><div class="eyebrow">METRÓNOMO</div><h2>Todo tiene su pulso.</h2><div class="tempo-controls"><button data-action="tempo" data-arg="-4" aria-label="Bajar cuatro BPM">−</button><div class="tempo-number"><span id="tempo-value">${ui.tempo}</span><small>BPM</small></div><button data-action="tempo" data-arg="4" aria-label="Subir cuatro BPM">+</button></div><input id="tempo-range" type="range" min="40" max="180" value="${ui.tempo}" aria-label="Tempo"><div class="beat-dots" id="beat-dots">${Array.from({length:ui.beats},()=>'<i></i>').join('')}</div><label class="field"><span>Clics por ciclo</span><select id="beats-select" style="width:100px;margin:10px auto 20px;display:block">${[2,3,4,6].map(x=>`<option ${x===ui.beats?'selected':''}>${x}</option>`).join('')}</select></label><button id="metro-button" data-action="metronome" class="btn secondary">${icon('play',14)}Iniciar metrónomo</button><p class="small muted mt">Decide qué figura representa el clic. Seis clics no interpretan automáticamente un compás de 6/8.</p></section></div><section class="card spaced"><div class="eyebrow">TECLADO DE REFERENCIA</div><h2>Oír, imaginar y responder.</h2><div class="mt">${fingerboard()}</div><div class="btn-group mt">${btn('Escuchar patrón 1–2–3–2–1','play-sequence',voiceSeq([0,2,4,2,0]).join(',')+'|60','secondary','volume')}</div></section><div class="note mt-lg">${icon('mic',15)} El micrófono requiere HTTPS y permiso. El análisis ocurre en este dispositivo. Usa una habitación tranquila y detén la referencia antes de cantar en un control. ${actionLink('Ayuda','mic-help')}</div>`;}
  function earPanel(){const choices=[[2,'2ª mayor'],[3,'3ª menor'],[4,'3ª mayor'],[7,'5ª justa'],[12,'Octava']];return `<div class="grid-2"><section class="card center"><div class="eyebrow">ESCUCHA ACTIVA</div><h2>El oído también se entrena.</h2><p class="mt">Escucha dos notas sucesivas. Canta la distancia y elige el intervalo. Todos los ejemplos son ascendentes.</p><div style="font:66px Georgia;color:#8fa17b;margin:24px 0">♫</div>${btn(ui.ear?'Escuchar de nuevo':'Escuchar un intervalo','ear-play','','','volume')}<div class="ear-options">${choices.map(([n,label])=>`<button data-action="ear-answer" data-arg="${n}" ${!ui.ear||ui.earResult?'disabled':''}>${label}</button>`).join('')}</div>${ui.earResult?`<div class="note ${ui.earResult.correct?'success':'warn'}">${ui.earResult.correct?'Correcto.':'Escucha otra vez.'} ${E(choices.find(x=>x[0]===ui.ear.interval)[1])}: ${E(C.noteName(ui.ear.base))} → ${E(C.noteName(ui.ear.base+ui.ear.interval))}.</div><div class="mt">${btn('Nuevo intervalo','ear-next','','secondary','arrow')}</div>`:'<p class="small muted">La puntuación aparece después de responder.</p>'}<div class="rule"></div><p class="small muted">Esta sesión: ${ui.earScore[0]} aciertos de ${ui.earScore[1]} intentos. Este entrenamiento no sustituye el control instrumental.</p></section><section class="card"><div class="eyebrow">DEL OÍDO A LOS DEDOS</div><h2>Antes de comprobar, canta.</h2><ol class="step-list"><li>Escucha la primera nota y repítela con la voz a una octava cómoda.</li><li>Imagina la nota de llegada. Compara si la distancia resulta pequeña, media o amplia.</li><li>Canta las dos notas antes de compararlas con una referencia cómoda.</li><li>Comprueba el intervalo y escribe qué pares confundes para estudiarlos después.</li></ol><div class="note">Los ejemplos se generan con síntesis. La prueba no graba tu voz ni evalúa tu canto. El dictado de frases y la audición polifónica se trabajan en las clases superiores con ayuda docente.</div></section></div>`;}
  function repertoirePanel(){return `<div class="note mb">Ocho semillas originales para estudiar y transformar. Se adaptan a tu referencia; no son canciones comerciales ni repertorio oficial. Al copiarlas al taller se crea un punto de partida, no una obra terminada.</div><div class="repertoire-grid">${REPERTOIRE.map((p,i)=>`<section class="card repertoire-card"><span class="pill">Nivel ${p.level} · ${p.tempo} BPM</span><h2 class="mt">${E(p.title)}</h2><p class="mt">${E(p.description)}</p><div class="score-scroll">${C.scoreSvg(voiceSeq(p.pattern.slice(0,8)),{width:600,title:p.title})}</div><div class="btn-group">${btn('Escuchar','piece-play',i,'secondary sm','play')}${btn('Ver partitura','piece-score',i,'secondary sm','book')}${btn('Crear mi versión','piece-copy',i,'secondary sm','pen')}</div></section>`).join('')}</div>`;}
  function sessionPanel(){return `<div class="grid-2"><section class="card center"><div class="eyebrow">PRÁCTICA CONSCIENTE</div><h2>Haz espacio para la música.</h2><p class="mt">Elige un bloque de estudio. El tiempo registra práctica, nunca sustituye una evaluación.</p><div class="timer-digits" id="timer-digits">${formatTime(timerElapsed())}</div><p class="small muted" id="timer-label">${ui.timer.running?'Sesión en marcha':'Objetivo de sesión: '+ui.timer.goal+' minutos'}</p><div class="row" style="justify-content:center;margin:20px 0"><select id="timer-goal" aria-label="Duración de la sesión" style="width:130px" ${ui.timer.running?'disabled':''}>${[10,20,30,45,60].map(x=>`<option value="${x}" ${ui.timer.goal===x?'selected':''}>${x} minutos</option>`).join('')}</select><button class="btn" id="timer-button" data-action="timer">${icon(ui.timer.running?'pause':'play',14)}${ui.timer.running?'Pausar':'Iniciar'}</button></div>${btn('Terminar y registrar','timer-finish','','secondary sm','check')}<div class="note mt-lg">El cronómetro se pausa al ocultar la pestaña. Para estudiar sin el navegador visible, registra después los minutos reales en Mi progreso.</div></section><section class="card"><div class="eyebrow">DIARIO DE ESTUDIO</div><h2>Escucha lo que cambia.</h2><p class="mt">Anota qué trabajaste, qué escuchaste y cuál será tu siguiente paso.</p><form data-form="journal"><label class="field mt"><span>Mi observación de hoy</span><textarea name="entry" required minlength="10" maxlength="3000" placeholder="Hoy trabajé Do5–Re5. A 56 BPM coordiné los dedos; necesito anticipar la llave de octava…"></textarea></label><button type="submit" class="btn mt">${icon('save',14)} Guardar observación</button></form>${state.journal.slice(-3).reverse().map(j=>`<div class="journal-entry"><time>${E(j.date)}</time><p>${E(j.text)}</p></div>`).join('')}</section></div>`;}
  function editSelection(){return {m:Number($('#edit-note')?.value||ui.editNote||state.settings.base),d:Number($('#edit-duration')?.value||ui.editDuration||1),breath:$('#edit-breath')?.checked??ui.editBreath??false,spell:$('#edit-spell')?.value||ui.editSpelling||'sharp',lyric:String($('#edit-lyric')?.value||ui.editLyric||'').slice(0,50)};}
  function composePage(){
    if(!state.composition){state.composition=C.newPiece(state.settings.base);save();}const p=state.composition;ui.bar=Math.min(ui.bar,p.bars.length-1);const tab=ui.songTab||'lyrics',a=C.analysePiece(p,state.settings),b=p.bars[ui.bar],used=b.melody.reduce((s,e)=>s+e.d,0),section=ui.lyricSection||'verse',stats=C.lyricStats(p.lyrics[section]),chosen=ui.editNote||state.settings.base;
    const header=`<header class="page-head"><div><div class="eyebrow">TALLER DE CANCIONES</div><h1>Una idea que se vuelve música.</h1><p>Escribe, canta, escucha y vuelve a decidir.</p></div><div class="btn-group">${btn('Escuchar guía','compose-play','','secondary','play')}${btn('Detener','stop-sound','','secondary','pause')}${btn('Exportar','compose-export','','','download')}${btn('Importar','import-project','','secondary','upload')}<input type="file" id="project-import" accept="application/json,.json" hidden></div></header><div class="tabs" role="tablist" aria-label="Espacios de composición">${[['lyrics','Letra e intención'],['music','Melodía y acordes'],['review','Oyentes y revisión']].map(([id,label])=>`<button class="tab ${tab===id?'active':''}" role="tab" aria-selected="${tab===id}" data-action="song-tab" data-arg="${id}">${label}</button>`).join('')}</div>`;
    const metadata=`<section class="card"><div class="grid-2"><label class="field"><span>Título</span><input id="piece-title" value="${E(p.title)}" maxlength="100"></label><label class="field"><span>Frase gancho</span><input data-song-field="hook" value="${E(p.hook)}" maxlength="300" placeholder="La frase que concentra tu idea…"></label></div><label class="field mt"><span>Intención, narrador y posible público</span><textarea data-song-field="brief" maxlength="2000">${E(p.brief)}</textarea></label><p class="small muted mt">Guardado automático en este navegador. Conserva copias del proyecto y de tus grabaciones por separado.</p></section>`;
    if(tab==='lyrics')return header+`<div class="composition-layout"><article>${metadata}<section class="card spaced"><div class="row between wrap"><h2>Cada sección tiene una función.</h2><span class="pill">${stats.lines} líneas · ${stats.words} palabras</span></div><div class="voice-switch mt">${Object.entries(C.SECTIONS).map(([id,name])=>`<button data-action="lyric-section" data-arg="${id}" class="${section===id?'active':''}">${E(name)}</button>`).join('')}</div><p class="mt small muted">${E(C.SECTION_PROMPTS[section])}</p><label class="field mt"><span>${E(C.SECTIONS[section])} · letra propia</span><textarea id="song-lyrics" data-section="${section}" maxlength="6000" class="lyric-editor" placeholder="Empieza con una imagen, una acción o una pregunta…">${E(p.lyrics[section])}</textarea></label><div id="lyric-stats" class="small muted mt">${stats.lines} líneas · ${stats.words} palabras</div><p class="small muted mt">Este conteo no mide sílabas cantadas, sinalefas ni calidad de rima. Comprueba prosodia leyendo y cantando.</p>${btn('Revisar líneas','lyric-analyse','','secondary mt','check')}${ui.lyricAnalysis?`<table class="review-table mt"><thead><tr><th>Línea</th><th>Palabras</th><th>Final</th></tr></thead><tbody>${stats.rows.map((r,i)=>`<tr><td>${i+1}. ${E(r.line)}</td><td>${r.words}</td><td>${E(r.last)}</td></tr>`).join('')}</tbody></table>`:''}</section><section class="card spaced"><h2>Decide qué vas a probar.</h2><ol class="step-list"><li>Lee la letra como conversación y marca apoyos naturales.</li><li>Canta una línea en pocas notas y comprueba qué palabras se entienden.</li><li>Prueba otro ritmo sin cambiar la idea.</li><li>Guarda una copia antes de una revisión grande.</li></ol>${btn('Llevarla a la música','song-tab','music','','arrow')}</section></article><aside class="editor-aside"><section class="card"><div class="eyebrow">UNA CONSIGNA PARA EMPEZAR</div><h3>${E(C.PROMPTS[ui.promptIndex||0][0])}</h3><p class="mt">${E(C.PROMPTS[ui.promptIndex||0].slice(1).join(' · '))}</p>${btn('Otra consigna','prompt','','secondary mt','pen')}<p class="small muted mt">Consignas originales predefinidas. No generan letras ni garantizan originalidad de tu resultado.</p></section><section class="card spaced"><h3>Una pregunta por revisión.</h3><p class="mt">¿La escena se entiende? ¿El estribillo expresa la idea? ¿Qué podría recordar alguien sin mirar?</p>${btn('Escuchar a oyentes','song-tab','review','secondary mt','ear')}</section></aside></div>`;
    if(tab==='review'){const f=a.audience;return header+`<div class="composition-layout"><article><section class="card"><div class="eyebrow">OBSERVACIONES, SIN PRONÓSTICOS</div><h2>¿Qué llegó al otro lado?</h2><p class="mt">Pide por tu cuenta a personas dispuestas que escuchen la demo y registra sus respuestas reales. No expliques qué deberían recordar antes de preguntar. La app no contacta a nadie ni verifica estas declaraciones.</p><div class="feedback-summary"><div><b>${f.n}</b><span>escuchas declaradas</span></div><div><b>${f.n?f.clarity.toFixed(1):'—'}</b><span>claridad media / 5</span></div><div><b>${f.again}</b><span>querrían repetir</span></div></div><p class="small muted mt">Una muestra pequeña describe estas respuestas; no representa el mercado ni predice éxito. El recuerdo se conserva en sus propias palabras.</p><form data-form="listener" class="mt"><div class="grid-2"><label class="field"><span>Alias del oyente</span><input name="alias" maxlength="60" placeholder="Oyente 1"></label><label class="field"><span>Claridad de la idea, según el oyente</span><select name="clarity">${[1,2,3,4,5].map(n=>`<option value="${n}" ${n===3?'selected':''}>${n}/5</option>`).join('')}</select></label></div><label class="field mt"><span>¿Qué frase o idea recuerda, sin mirar?</span><textarea name="recall" maxlength="300"></textarea></label><label class="field mt"><span>Observación abierta · mínimo 10 caracteres</span><textarea name="comment" required minlength="10" maxlength="1000"></textarea></label><label class="check"><input type="checkbox" name="again">Declara que querría volver a escucharla.</label><label class="check"><input type="checkbox" name="listened" required>Confirmo que esta persona escuchó y son sus respuestas reales.</label><button class="btn mt" type="submit">${icon('save',14)}Guardar observación</button></form></section><section class="card spaced"><h2>Lo que realmente dijeron.</h2>${p.feedback.length?p.feedback.map((x,i)=>`<div class="listener-entry"><div class="row between"><h3>${E(x.alias)} · ${x.clarity}/5</h3><button class="icon-btn" data-action="feedback-remove" data-arg="${i}" aria-label="Eliminar observación ${i+1}">${icon('trash',14)}</button></div><p class="mt">${E(x.comment)}</p><p class="small muted mt">Recuerdo libre: ${E(x.recall||'Sin respuesta')} · ${x.again?'Quiere volver a escuchar':'Sin deseo declarado de repetir'} · ${x.listened?'Escucha confirmada por ti':'Escucha sin confirmar'}</p></div>`).join(''):'<p class="mt muted">Todavía no hay observaciones guardadas.</p>'}</section><section class="card spaced"><h2>La revisión que eliges hacer.</h2><label class="field mt"><span>Qué cambió, por qué y qué escuchaste · final: mínimo 50 caracteres</span><textarea data-song-field="revision" maxlength="3000">${E(p.revision)}</textarea></label><label class="field mt"><span>Defensa final · 150–300 palabras</span><textarea id="piece-notes" maxlength="5000">${E(p.notes)}</textarea></label><div id="piece-wordcount" class="small muted mt">${a.words} palabras</div><label class="field mt"><span>Plan de salida · objetivo, público, materiales, fecha propuesta y revisión</span><textarea data-song-field="release" maxlength="3000">${E(p.release)}</textarea></label><p class="small muted mt">El plan no publica ni programa acciones. La calidad y los acuerdos de autoría se revisan con personas responsables del proyecto.</p></section></article><aside class="editor-aside">${analysisCard(a)}</aside></div>`;}
    return header+`<div class="composition-layout"><article><section class="card"><div class="grid-3"><label class="field"><span>Tonalidad escrita</span><select id="piece-key">${Object.keys(C.KEYS).map(k=>`<option value="${k}" ${p.key===k?'selected':''}>${E(k)} ${k.endsWith('m')?'menor':'mayor'}</option>`).join('')}</select></label><label class="field"><span>Tempo · negras por minuto</span><input id="piece-tempo" type="number" min="40" max="180" value="${p.tempo}"></label><label class="field"><span>Escuchar guía</span><select id="playback-mode">${[['both','Melodía y acordes'],['melody','Solo melodía'],['chords','Solo acordes']].map(([id,name])=>`<option value="${id}" ${(ui.playbackMode||'both')===id?'selected':''}>${name}</option>`).join('')}</select></label></div><p class="small muted mt">Cambiar tonalidad aquí cambia la armadura, no las notas ni acordes. Para mover la canción completa usa Transportar.</p><div class="row wrap mt">${btn('Transportar −1','transpose','-1','secondary sm')}${btn('Transportar +1','transpose','1','secondary sm')}${btn('Cargar semilla','compose-example','','secondary sm','book')}</div><div class="rule"></div><h3>${p.bars.length} compases · selecciona uno para editar.</h3><div class="bars-grid mt">${p.bars.map((bar,i)=>{const sum=bar.melody.reduce((s,e)=>s+e.d,0);return `<button class="piece-bar ${ui.bar===i?'active':''}" data-action="bar" data-arg="${i}" aria-label="Editar compás ${i+1}, ${sum} de cuatro pulsos"><span class="bar-title">${String(i+1).padStart(2,'0')} · ${E(C.SECTIONS[bar.section])}</span><b>${E(bar.chord)}</b><span class="bar-events">${bar.melody.length?bar.melody.map(e=>`<span>${e.m===null?'sil.':E(C.noteName(e.m,e.spell==='flat'))}<i> ${e.d}</i></span>`).join(''):'<i>Tu primera nota…</i>'}</span><span class="bar-beats ${sum===4?'full':''}" style="display:block">${sum}/4 pulsos</span></button>`;}).join('')}</div><div class="btn-group mt">${p.bars.length<32?btn('Añadir compás','bar-add','','secondary sm'):''}${p.bars.length>1?btn('Quitar último','bar-remove','','secondary sm'):''}</div></section><section class="sheet spaced"><div class="sheet-header"><h3>Compás ${ui.bar+1} · ${E(b.chord)}</h3><span class="small muted">4/4 · ${E(C.SECTIONS[b.section])}</span></div><div class="score-scroll">${C.scoreSvg(b.melody,{width:700,title:'Compás '+(ui.bar+1)+' de '+p.title})}</div><div class="sheet-footer">Altura de concierto · texto añadido manualmente bajo notas · guía sintetizada</div></section><section class="card spaced"><h2>La voz decide la viabilidad.</h2><p class="mt">La guía no respira ni pronuncia palabras. Canta la frase, comprueba apoyos y respiraciones, y revisa con docente. Zona declarada: ${E(C.noteName(state.settings.low,true))} – ${E(C.noteName(state.settings.high,true))}.</p>${a.warnings.some(x=>x.includes('zona cómoda'))?'<div class="note warn mt">Hay alturas fuera de tu zona cómoda declarada. Revisa o transporta antes de cantarlas.</div>':''}</section></article><aside class="editor-aside"><section class="card"><h3>Tu compás ${ui.bar+1}.</h3><label class="field mt"><span>Sección</span><select id="bar-section">${Object.entries(C.SECTIONS).map(([id,name])=>`<option value="${id}" ${b.section===id?'selected':''}>${E(name)}</option>`).join('')}</select></label><label class="field mt"><span>Acorde · cifrado C, Am, G7…</span><input id="bar-chord" value="${E(b.chord)}" list="chord-options" maxlength="8"><datalist id="chord-options">${C.chordPalette().map(ch=>`<option value="${ch}"></option>`).join('')}</datalist></label><label class="field mt"><span>Altura de concierto</span><select id="edit-note">${Array.from({length:49},(_,i)=>36+i).map(m=>`<option value="${m}" ${chosen===m?'selected':''}>${E(C.noteName(m,ui.editSpelling==='flat'))}${m<state.settings.low||m>state.settings.high?' · fuera de tu zona':''}</option>`).join('')}</select></label><label class="field mt"><span>Duración en negras</span><select id="edit-duration">${[[1,'Negra · 1'],[.5,'Corchea · ½'],[.25,'Semicorchea · ¼'],[1.5,'Negra con puntillo · 1½'],[2,'Blanca · 2'],[3,'Blanca con puntillo · 3'],[4,'Redonda · 4']].map(([d,name])=>`<option value="${d}" ${(ui.editDuration||1)===d?'selected':''}>${name}</option>`).join('')}</select></label><label class="field mt"><span>Texto bajo esta nota · opcional</span><input id="edit-lyric" maxlength="50" value="${E(ui.editLyric||'')}" placeholder="Sílaba o palabra"></label><label class="check mt"><input type="checkbox" id="edit-breath" ${ui.editBreath?'checked':''}>Respirar después de esta nota</label><label class="field mt"><span>Notas cromáticas</span><select id="edit-spell"><option value="sharp">Con sostenido</option><option value="flat" ${ui.editSpelling==='flat'?'selected':''}>Con bemol</option></select></label><div class="note mt" id="edit-preview">${E(C.noteName(chosen,true))} · ${4-used} pulsos disponibles</div>${btn('Añadir nota','event-add','note','w-full mt','music')}${btn('Añadir silencio','event-add','rest','secondary w-full mt')}${btn('Escuchar referencia','edit-listen','','secondary w-full mt','volume')}<div class="rule"></div>${b.melody.map((e,i)=>`<div class="event-row"><span>${e.m===null?'Silencio':E(C.noteName(e.m,e.spell==='flat'))}</span><span class="small muted">${E(e.lyric||'')}${e.breath?' ’':''}</span><span>${e.d}</span><button class="icon-btn" data-action="event-remove" data-arg="${i}" aria-label="Eliminar evento ${i+1}">${icon('trash',13)}</button></div>`).join('')}</section><div class="spaced">${analysisCard(a)}</div></aside></div>`;
  }
  function progressPage(){const c=completed(),ex=D.levels.filter(x=>C.examPassed(state,x.id)).length,days=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);days.push({key:C.dateKey(d),name:d.toLocaleDateString('es',{weekday:'short'}),minutes:Math.round(state.practice[C.dateKey(d)]||0)});}const max=Math.max(state.settings.goal,...days.map(d=>d.minutes));return `<header class="page-head"><div><div class="eyebrow">TU RECORRIDO, A TU RITMO</div><h1>El avance se hace audible.</h1><p>Conserva tus observaciones, reconoce la constancia y vuelve a lo que necesita más atención.</p></div>${btn('Exportar progreso','backup','','secondary','download')}</header><div class="grid-3"><section class="card"><div class="eyebrow">CLASES COMPLETADAS</div><div class="progress-total">${c}<span style="font:18px sans-serif;color:#9ba68f"> / 48</span></div><div class="progress-line"><span style="width:${c/48*100}%"></span></div></section><section class="card"><div class="eyebrow">NIVELES CERRADOS</div><div class="progress-total">${ex}<span style="font:18px sans-serif;color:#9ba68f"> / 8</span></div><p class="small">Con voz, creación y evidencia.</p></section><section class="card"><div class="eyebrow">PRÁCTICA REGISTRADA</div><div class="progress-total">${totalMinutes()}<span style="font:15px sans-serif;color:#9ba68f"> min</span></div><p class="small">Cronómetro y sesiones declaradas.</p></section></div><div class="grid-2 mt-lg"><section class="card"><div class="eyebrow">TU MAPA DE APRENDIZAJE</div><h2>Cada paso tiene su lugar.</h2>${D.levels.map(l=>`<div class="mt"><div class="row between"><span class="small">0${l.id} · ${E(l.name)}</span><span class="small muted">${countLevel(l.id)}/6 ${C.examPassed(state,l.id)?'· Nivel aprobado':''}</span></div><div class="progress-matrix">${D.lessons.filter(x=>x.level===l.id).map(x=>`<a class="${C.lessonDone(state,x.id)?'complete':''}" href="#/lesson/${x.id}" title="${E(x.title)}" style="display:contents"><span class="${C.lessonDone(state,x.id)?'complete':''}">${C.lessonDone(state,x.id)?icon('check',12):String(x.id).padStart(2,'0')}</span></a>`).join('')}</div></div>`).join('')}</section><section class="card"><div class="eyebrow">ÚLTIMOS SIETE DÍAS</div><h2>La constancia se cultiva.</h2><div class="day-chart">${days.map((d,i)=>`<div class="day-col ${i===6?'today':''}"><b>${d.minutes} min</b><div style="height:${d.minutes/max*78}px"></div><small>${E(d.name)}</small></div>`).join('')}</div><p class="small muted mt">Objetivo diario: ${state.settings.goal} minutos. El tiempo ayuda a organizarte; la calidad se revisa en tus evidencias.</p><div class="rule"></div><h3>¿Practicaste fuera de pantalla?</h3><form data-form="manual-time"><div class="grid-2 mt"><label class="field"><span>Fecha</span><input type="date" name="date" required max="${C.dateKey()}" value="${C.dateKey()}"></label><label class="field"><span>Minutos reales</span><input type="number" name="minutes" min="1" max="240" required placeholder="20"></label></div><button class="btn secondary mt" type="submit">Registrar sesión declarada</button></form><div class="note mt">Los datos pertenecen a este navegador. Descarga las grabaciones desde cada control de nivel y exporta el progreso para conservarlos.</div></section></div><section class="card spaced"><div class="section-head"><h2>Lo que escuchaste en el camino.</h2>${actionLink('Añadir observación','go','practice/journal','pen')}</div>${state.journal.length?state.journal.slice().reverse().map(j=>`<div class="journal-entry"><time>${E(j.date)}</time><p>${E(j.text)}</p></div>`).join(''):'<p class="muted small">Tu diario empieza con una observación. Describe algo concreto que quieras mejorar en tu próxima sesión.</p>'}</section>`;}
  function methodPage(){return `<header class="page-head"><div><div class="eyebrow">EL MÉTODO VERSO</div><h1>Voz, intención<br>y trabajo de autor.</h1><p>Canto y composición desde cero hasta un proyecto de preparación preuniversitaria.</p></div></header><div class="grid-2"><section class="card"><h2>Una ruta de ocho etapas.</h2><p class="mt">48 clases y 144 preguntas combinan oído, referencia cómoda, lectura, ritmo, dicción, técnica guiada, letra, prosodia, gancho, melodía, armonía, forma, demo, oyentes y preparación de un proyecto. Los minutos incluyen escritura, escucha y pausas, no canto continuo. El dominio requiere práctica sostenida y acompañamiento docente.</p><p>Cada clase exige comprensión 3/3, una secuencia vocal, un ejercicio escrito y observación. El nivel añade teoría 80%, control de regularidad con 70% de intervalos entre ataques dentro de tolerancia y una toma guardada. Desde nivel 3: revisión docente de 16/20, sin criterios por debajo de 3/5.</p><p>Los proyectos crecen: letra desde nivel 3; ocho compases desde nivel 4; canción de dieciséis compases desde nivel 6; tres oyentes y una revisión desde nivel 7; defensa y plan desde nivel 8. Las condiciones mínimas verifican material, no su calidad.</p></section><section class="card"><h2>Una referencia, sin etiquetas.</h2><p class="mt">Elige una altura y límites cómodos antes de las pruebas. No son extensión máxima ni clasificación vocal. Los patrones se transportan y quedan bloqueados si no caben en la zona declarada. Puedes estudiar lectura y escritura sin cantar fuera de ella.</p><p>El detector estima una altura predominante, octava, estabilidad y orden; a tempo compara intervalos entre ataques. No evalúa salud, esfuerzo, timbre, dicción ni identidad. Ruido, armónicos, vibrato y señal débil pueden causar errores. Las pruebas apagan referencias y metrónomo sonoro.</p><p>La técnica requiere observación docente. Ante molestias, detén el ejercicio y busca orientación apropiada. Esta app es educativa, no diagnostica ni trata problemas de voz.</p></section></div><section class="card spaced"><h2>Crear canciones que puedan conectar.</h2><p class="mt">Verso enseña herramientas para escribir y revisar canciones con identidad y claridad. No garantiza éxito comercial ni asigna una puntuación predictiva. El público, el contexto, la interpretación, la producción y la distribución influyen en los resultados.</p><p>Las observaciones de oyentes son registros manuales y declarados. La app no contacta a personas, verifica identidades, importa estadísticas ni publica canciones. Una muestra pequeña no representa un mercado. El criterio artístico sigue siendo parte de cada revisión.</p><p>El taller trabaja en 4/4 con figuras hasta semicorcheas, puntillos, silencios, acordes por compás y texto manual por nota. No reconoce letras cantadas, cuenta sílabas métricas, detecta plagio ni alinea todo automáticamente. Exporta JSON, hoja de canción y MusicXML para edición adicional. La guía sintetizada no es una grabación de voz ni una mezcla final.</p></section><section class="card spaced"><h2>Datos, privacidad y alcance.</h2><p class="mt">El progreso, diario y canción se guardan en este navegador. Las grabaciones están en almacenamiento local separado y no se incluyen en la copia JSON. No hay cuentas ni sincronización: descarga los audios desde cada control y tus copias desde Ajustes. Borrar datos del navegador puede eliminar el trabajo.</p><p>El micrófono necesita HTTPS o localhost compatible y permiso. El análisis de las pruebas no graba ni envía audio. Las tomas del portafolio permanecen locales; el hosting puede mantener sus registros normales de página. Los formularios docentes son declarados y no certifican identidad. No se emiten títulos ni equivalencias oficiales; consulta los requisitos del centro para una admisión real.</p></section><section class="card spaced"><h2>Referencias de consulta.</h2><p class="mt">El programa, consignas y semillas musicales son originales. Estos enlaces amplían consulta y no implican afiliación ni homologación.</p><ul class="analysis-list"><li><a href="https://www.nidcd.nih.gov/es/espanol/cuidando-su-voz" target="_blank" rel="noopener noreferrer">NIDCD · Cuidado de la voz</a>.</li><li><a href="https://online.berklee.edu/takenote/prosody-in-music-and-songwriting/" target="_blank" rel="noopener noreferrer">Berklee Online · Prosodia y composición</a>.</li><li><a href="https://college.berklee.edu/songwriting/songwriting-courses" target="_blank" rel="noopener noreferrer">Berklee · Áreas de aprendizaje de composición</a>.</li><li><a href="https://artists.spotify.com/blog/release-details-page-and-audience-engagement-analytics" target="_blank" rel="noopener noreferrer">Spotify for Artists · Contexto de estadísticas de audiencia</a>.</li><li><a href="https://www.w3.org/2021/06/musicxml40/" target="_blank" rel="noopener noreferrer">W3C · MusicXML 4.0</a>.</li></ul><dl class="glossary">${Object.entries(D.glossary).map(([t,d])=>`<dt>${E(t)}</dt><dd>${E(d)}</dd>`).join('')}</dl></section>`;}
  function modal(content){stopAssessment();A.stopSounds();ui.metro=false;ui.tuning=false;if(ui.recording)stopRecording();const dialog=$('#dialog');dialog.innerHTML=`<div class="dialog-inner"><button class="icon-btn close" data-action="close" aria-label="Cerrar ventana">${icon('close',20)}</button>${content}</div>`;if(!dialog.open)dialog.showModal();}
  function closeModal(){$('#dialog').close();}
  function intro(id){modal(`<div class="eyebrow">BIENVENIDO A VERSO</div><h2>Tu voz.<br>Tu forma de decirlo.</h2><p>Prepara un lugar tranquilo, un micrófono y un espacio para escribir. No necesitas otro voz: el teclado y las guías aportan referencias.</p><div class="onboarding-items"><div class="row">${icon('tune',20)}<span><b>Primero, una zona cómoda.</b><br>En Ajustes elige referencia y límites actuales. No son una clasificación vocal ni una meta de extensión.</span></div><div class="row">${icon('mic',20)}<span><b>Canta y escucha.</b><br>Las pruebas usan tu micrófono; la técnica necesita observación docente.</span></div><div class="row">${icon('pen',20)}<span><b>Escribe y revisa.</b><br>Las letras, melodías y comentarios son trabajo propio. La app no predice éxitos.</span></div></div><div class="note mt">Los bloques alternan canto breve, escucha, escritura y descanso. Puedes leer primero y configurar antes del control.</div>${btn('Comenzar mi primera clase','intro-start',id,'w-full mt-lg','arrow')}`);}
  function settings(){const options=(chosen,min,max)=>Array.from({length:max-min+1},(_,i)=>i+min).map(m=>`<option value="${m}" ${m===chosen?'selected':''}>${E(C.noteName(m,true))}</option>`).join('');modal(`<div class="eyebrow">TU REFERENCIA VOCAL</div><h2>Una zona cómoda hoy.</h2><p>No busques extremos para rellenar estos campos. Elige con ayuda docente si no sabes qué alturas te resultan cómodas. Puedes leer y componer mientras las pruebas quedan pendientes.</p><form data-form="settings"><div class="grid-3 mt"><label class="field"><span>Nota de partida</span><select name="base">${options(state.settings.base,40,72)}</select></label><label class="field"><span>Límite cómodo inferior</span><select name="low">${options(state.settings.low,36,84)}</select></label><label class="field"><span>Límite cómodo superior</span><select name="high">${options(state.settings.high,36,84)}</select></label></div><label class="check mt"><input type="checkbox" name="confirmed" ${state.settings.confirmed?'checked':''}>He elegido una zona cómoda, sin forzar ni usar mi extensión máxima.</label><div class="grid-2 mt"><label class="field"><span>Objetivo total de estudio · minutos</span><input type="number" name="goal" min="5" max="120" value="${state.settings.goal}" required></label><label class="field"><span>La4 de concierto · Hz</span><input type="number" name="a" min="436" max="444" step=".1" value="${state.settings.a}" required></label></div><p class="small muted mt">Las pruebas se transportan a la referencia. Si un patrón no cabe, no se habilita. Los resultados anteriores conservan la referencia usada.</p><button type="submit" class="btn mt">${icon('save',14)}Guardar referencia</button></form><div class="rule"></div><h3>Conserva lo que creas.</h3><p>JSON de progreso incluye diario y canción, pero no audios. Descarga cada grabación desde su control. No hay sincronización ni cuentas separadas por estudiante.</p><div class="btn-group mt">${btn('Descargar mi copia','backup','','secondary','download')}${btn('Importar copia','import-backup','','secondary','upload')}</div><input type="file" id="progress-import" accept="application/json,.json" hidden><div class="mt-lg">${btn('Borrar datos de Verso en este navegador','reset-ask','','secondary sm','trash')}</div>`);}
  function download(data,name,type='application/json'){const blob=data instanceof Blob?data:new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
  function backup(){saveTimerChunk();download(JSON.stringify({...state,exportedAt:new Date().toISOString(),mediaIncluded:false},null,2),'verso-canto-progreso-'+C.dateKey()+'.json');toast('Copia descargada. Las grabaciones se conservan por separado.');}
  function formatTime(seconds){const s=Math.max(0,Math.floor(seconds));return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');}
  function timerElapsed(){return ui.timer.elapsed+(ui.timer.running?(performance.now()-ui.timer.start)/1000:0);}
  function saveTimerChunk(){const t=ui.timer,elapsed=timerElapsed(),added=elapsed-t.logged;if(added>=1){const key=C.dateKey();state.practice[key]=Math.min(1440,(state.practice[key]||0)+added/60);t.logged=elapsed;save();}}
  function updateTimerDisplay(){const elapsed=timerElapsed();if($('#timer-digits'))$('#timer-digits').textContent=formatTime(elapsed);if(ui.timer.running&&elapsed>=ui.timer.goal*60){pauseTimer();toast('Bloque terminado. Descansa y anota una observación.');if(ui.view==='practice'&&ui.practiceTab==='journal')render();}}
  function pauseTimer(){if(!ui.timer.running)return;saveTimerChunk();ui.timer.elapsed=timerElapsed();ui.timer.running=false;clearInterval(ui.timer.interval);}
  function toggleTimer(){if(ui.timer.running)pauseTimer();else{if(ui.timer.elapsed>=ui.timer.goal*60){ui.timer.elapsed=0;ui.timer.logged=0;}ui.timer.running=true;ui.timer.start=performance.now();ui.timer.interval=setInterval(()=>{updateTimerDisplay();saveTimerChunk();},1000);}render();}
  async function beginAssessment(kind,id){
    if(ui.assessment){stopAssessment();$('#live-note').textContent='Prueba detenida · no se ha aprobado';$('#assessment-start').innerHTML=icon('mic',13)+'Volver a intentar';$('#live-wave')?.classList.remove('listening');return;}
    if(ui.busy)return;
    const lesson=kind==='lesson'?D.lessons[id-1]:null,level=D.levels[(lesson?.level||id)-1],open=lesson?C.unlocked(state,lesson,D.lessons):C.examReady(state,id,D.lessons);
    if(!open){toast('Completa primero los requisitos anteriores de la ruta.');return;}
    if(ui.recording){toast('Termina la grabación antes de comenzar una prueba.');return;}if(!C.fits(voiceSeq(lesson?lesson.sequence:level.exam),state.settings)){toast('Confirma una zona cómoda que contenga el patrón antes de intentar la prueba.');return;}
    ui.busy=true;ui.metro=false;A.stopSounds();const run={kind,id,targets:voiceSeq(lesson?lesson.sequence:level.exam),activeAfter:Infinity,level};run.sequence=new C.Sequence(run.targets,{cents:level.cents,tempo:level.tempo,timed:kind==='exam',tolerance:level.id<3?.35:.30,hold:level.hold});ui.assessment=run;
    $('#assessment-start').disabled=true;$('#live-note').textContent='Solicitando acceso al micrófono…';
    try{const started=await A.startMic((p,t,ended)=>{
      if(ui.assessment!==run)return;
      if(ended){stopAssessment();toast('El micrófono se desconectó. La prueba sigue pendiente.');render();return;}
      if(p){const raw=C.midi(p.frequency,state.settings.a),m=Math.round(raw),cent=Math.round((raw-m)*100);if($('#live-note'))$('#live-note').textContent=`Escuchando ${C.noteName(m,true)} · ${cent>0?'+':''}${cent} cents`;}
      else if($('#live-note'))$('#live-note').textContent='Escuchando… canta una nota recta y cómoda.';
      if(t<run.activeAfter){const remaining=Math.ceil((run.activeAfter-t)/(60000/level.tempo));if($('#live-hint'))$('#live-hint').textContent=Number.isFinite(remaining)?`Prepárate: ${remaining} pulsos. Empieza con ${C.noteName(run.targets[0])}.`:'Preparando la entrada de audio…';return;}
      if($('#visual-beat')&&kind==='exam')$('#visual-beat').textContent='Pulso '+(Math.floor((t-run.activeAfter)/(60000/level.tempo))%4+1)+' / 4 · '+level.tempo+' BPM';
      const result=run.sequence.feed(p,t,state.settings.a);
      if($('#live-meter'))$('#live-meter').style.width=Math.round((result.holding||0)*100)+'%';
      if(result.accepted||result.done){for(let i=0;i<result.index;i++)if($('#seq-'+i))$('#seq-'+i).style.background='#456b35';if(!result.done){const target=run.targets[result.index];$('#live-target').innerHTML=E(C.noteName(target))+'<small id="live-location">'+E(C.locName(target))+'</small>';$('#live-hint').textContent=`${result.index} de ${run.targets.length} · siguiente nota: ${C.noteName(target)}${kind==='exam'?' · mantén el pulso':''}`;}}
      if(result.done){stopAssessment();ui.busy=false;if(result.passed){const r=kind==='lesson'?lessonRecord(id):examRecord(id);r.practical=true;r.reference=state.settings.base;save();render();if($('#live-hint'))$('#live-hint').textContent=kind==='exam'?`Secuencia aprobada · regularidad: ${result.rhythmScore}% de intervalos dentro de tolerancia.`:'Secuencia reconocida. Completa también teoría y autoobservación.';toast(kind==='exam'?'Secuencia vocal aprobada. Regularidad medida: '+result.rhythmScore+'%.':'La secuencia de la clase está aprobada.');}else{$('#assessment-start').disabled=false;$('#assessment-start').innerHTML=icon('mic',13)+'Repetir con pulso';$('#live-wave')?.classList.remove('listening');$('#live-hint').textContent=`Alturas correctas. Regularidad: ${result.rhythmScore}%; necesitas al menos 70%. Practica con el metrónomo y repite.`;toast('Secuencia correcta, pero el pulso necesita otra toma.');}}
    });
      if(!started||ui.assessment!==run){ui.busy=false;return;}
      run.activeAfter=performance.now()+(kind==='exam'?4:2)*60000/level.tempo;ui.busy=false;$('#assessment-start').disabled=false;$('#assessment-start').innerHTML=icon('pause',13)+'Detener prueba';$('#live-wave')?.classList.add('listening');
      ui.assessmentTimeout=setTimeout(()=>{if(ui.assessment===run){stopAssessment();render();toast('La prueba se detuvo tras dos minutos. Puedes volver a intentarlo.');}},120000);
    }catch(e){stopAssessment();ui.busy=false;render();toast(e.message);if($('#live-hint'))$('#live-hint').textContent=e.message;}
  }
  async function toggleTuner(){if(ui.tuning){A.stopMic();ui.tuning=false;$('#tuner-button').innerHTML=icon('mic',14)+'Activar escucha';$('#tuner-cents').textContent='Micrófono apagado.';return;}if(ui.busy)return;ui.busy=true;A.stopSounds();ui.metro=false;const token=ui.render;$('#tuner-button').disabled=true;try{const started=await A.startMic((p,t,ended)=>{if(ended){ui.tuning=false;render();toast('Se desconectó el micrófono.');return;}if(!p){if($('#tuner-cents'))$('#tuner-cents').textContent='Buscando una nota clara…';return;}const raw=C.midi(p.frequency,state.settings.a),m=Math.round(raw),cent=Math.round((raw-m)*100);if(!$('#tuner-note'))return;$('#tuner-note').innerHTML=E(C.FLATS[((m%12)+12)%12])+'<small>'+String(Math.floor(m/12)-1)+'</small>';$('#tuner-hz').textContent=p.frequency.toFixed(1)+' Hz · altura de concierto';$('#tuner-needle').style.left=Math.max(2,Math.min(98,50+cent))+'%';$('#tuner-cents').textContent=(cent>0?'+':'')+cent+' cents'+(m<state.settings.low||m>state.settings.high?' · fuera de tu zona declarada':'');});if(started&&ui.render===token){ui.tuning=true;$('#tuner-button').disabled=false;$('#tuner-button').innerHTML=icon('pause',14)+'Apagar micrófono';}}catch(e){toast(e.message);if($('#tuner-cents'))$('#tuner-cents').textContent=e.message;if($('#tuner-button'))$('#tuner-button').disabled=false;}finally{ui.busy=false;}}
  async function metronome(){if(ui.metro){A.stopSounds();ui.metro=false;$('#metro-button').innerHTML=icon('play',14)+'Iniciar metrónomo';$$('#beat-dots i').forEach(x=>x.classList.remove('on'));return;}if(ui.recording){toast('Detén la grabación antes de iniciar el metrónomo sonoro.');return;}try{await A.startMetronome(ui.tempo,ui.beats,b=>{$$('#beat-dots i').forEach((x,i)=>x.classList.toggle('on',i===b));});ui.metro=true;if($('#metro-button'))$('#metro-button').innerHTML=icon('pause',14)+'Detener metrónomo';}catch(e){toast(e.message);}}
  function tempoChange(value){ui.tempo=Math.max(40,Math.min(180,Math.round(value)));if($('#tempo-value'))$('#tempo-value').textContent=ui.tempo;if($('#tempo-range'))$('#tempo-range').value=ui.tempo;if(ui.metro){A.stopSounds();ui.metro=false;metronome();}}
  async function playNotes(events,tempo=60){if(ui.recording){toast('Las referencias se silencian mientras grabas tu ejecución.');return;}try{await A.playEvents(events,{tempo,a:state.settings.a});}catch(e){toast(e.message);}}
  function repertoirePiece(index){const source=REPERTOIRE[index],p=C.newPiece(60);p.title=source.title+' · mi versión';p.tempo=source.tempo;p.bars=[];for(let i=0;i<Math.ceil(source.pattern.length/4);i++)p.bars.push({section:i<Math.ceil(source.pattern.length/8)?'verse':'chorus',chord:source.chords[i%source.chords.length],melody:source.pattern.slice(i*4,i*4+4).map((n,j)=>({...C.eventFor(60+n),...(source.words[i*4+j]?{lyric:source.words[i*4+j]}:{}),...(j===3?{breath:true}:{})}))});return C.transposePiece(p,state.settings.base-60);}
  async function playPiece(p){if(ui.recording){toast('Termina la grabación antes de escuchar una guía.');return;}try{await A.playPiece(p,state.settings.a,{mode:ui.playbackMode||'both'});}catch(e){toast(e.message);}}
  async function startRecording(levelId){
    if(ui.recording){stopRecording();return;}
    if(ui.busy)return;const level=D.levels[levelId-1];if(!C.examReady(state,levelId,D.lessons)){toast('Completa las seis clases antes de presentar la evidencia.');return;}
    if(!window.MediaRecorder){toast('Este navegador no admite grabación. Puedes aportar tu archivo de audio usando la opción inferior.');return;}
    if(!window.isSecureContext||!navigator.mediaDevices?.getUserMedia){toast('La grabación necesita HTTPS y acceso al micrófono desde una pestaña compatible.');return;}
    stopAssessment();A.stopSounds();ui.busy=true;const token=ui.render;const button=$('#record-button');if(button)button.disabled=true;let stream;
    try{stream=await navigator.mediaDevices.getUserMedia({audio:true,video:false});if(ui.render!==token){stream.getTracks().forEach(t=>t.stop());ui.busy=false;return;}const type=['audio/webm;codecs=opus','audio/mp4','audio/ogg;codecs=opus'].find(x=>MediaRecorder.isTypeSupported(x)),rec=new MediaRecorder(stream,type?{mimeType:type}:undefined),r={level:levelId,stream,rec,chunks:[],start:performance.now(),stopAt:0};ui.recording=r;rec.ondataavailable=e=>{if(e.data.size)r.chunks.push(e.data);};rec.onstop=async()=>{ui.pendingMedia=true;clearInterval(r.tick);stream.getTracks().forEach(t=>t.stop());const duration=((r.stopAt||performance.now())-r.start)/1000;const blob=new Blob(r.chunks,{type:rec.mimeType||type||'audio/webm'});ui.recording=null;ui.busy=false;if(duration<level.record||blob.size<500){ui.pendingMedia=false;toast('La toma duró '+Math.round(duration)+' s. Graba al menos '+level.record+' s para este nivel.');if(ui.view==='exam'&&ui.id===levelId)render();return;}try{await storeEvidence(levelId,blob,duration);}finally{ui.pendingMedia=false;}};rec.onerror=()=>{toast('La grabación se interrumpió. Revisa el dispositivo y vuelve a intentarlo.');stopRecording();};rec.start(1000);ui.busy=false;if(button){button.disabled=false;button.innerHTML=icon('pause',14)+'Terminar y guardar';}r.tick=setInterval(()=>{const elapsed=(performance.now()-r.start)/1000;if($('#record-status'))$('#record-status').innerHTML='<i class="record-indicator active"></i>Grabando '+formatTime(elapsed)+' · mínimo '+level.record+' s';if(elapsed>=300)stopRecording();},250);
    }catch(e){stream?.getTracks().forEach(t=>t.stop());ui.busy=false;if(button)button.disabled=false;toast('No se pudo grabar. Permite el micrófono, cierra otras grabadoras y vuelve a intentarlo.');}
  }
  function stopRecording(){const r=ui.recording;if(r&&r.rec.state!=='inactive'){r.stopAt=performance.now();clearInterval(r.tick);r.rec.stop();r.stream.getTracks().forEach(t=>t.stop());if($('#record-status'))$('#record-status').textContent='Guardando la toma…';if($('#record-button'))$('#record-button').disabled=true;}}
  function audioExt(type=''){return /mpeg|mp3/i.test(type)?'mp3':/wav/i.test(type)?'wav':/mp4|m4a/i.test(type)?'m4a':/ogg/i.test(type)?'ogg':'webm';}
  async function storeEvidence(id,blob,duration){const owner=state,old=owner.exams[id]?.evidence,key='level-'+id+'-'+Date.now();try{await VersoMedia.put(key,blob);if(state!==owner){await VersoMedia.remove(key);throw Error('Cambió el recorrido durante el guardado. Conserva esta toma y vuelve a aportarla.');}examRecord(id).evidence={id:key,duration,type:blob.type};save();if(old)VersoMedia.remove(old.id).catch(()=>{});if(ui.view==='exam'&&ui.id===id)render();toast('Grabación guardada en tu dispositivo. Descárgala para conservar una copia.');}catch(e){download(blob,'verso-canto-nivel-'+id+'.'+audioExt(blob.type));toast(e.message+' Se ha preparado una descarga de la toma; vuelve a aportarla cuando haya espacio.');if(ui.view==='exam'&&ui.id===id)render();}}
  async function loadEvidence(id){const e=state.exams[id]?.evidence,token=ui.render;if(!e||!$('#evidence-player'))return;try{const blob=await VersoMedia.get(e.id);if(ui.render!==token||!$('#evidence-player'))return;if(!blob){$('#evidence-player').innerHTML='<div class="note warn">La copia de progreso conserva este resultado, pero el audio no está en este dispositivo. Aporta o graba una toma para revisarlo aquí.</div>';return;}const url=URL.createObjectURL(blob);ui.mediaUrls.push(url);$('#evidence-player').innerHTML=`<audio controls preload="metadata" class="audio-player" src="${url}" aria-label="Grabación de voz del nivel ${id}"></audio><a class="text-link" href="${url}" download="verso-canto-nivel-${id}.${audioExt(e.type)}">${icon('download',13)}Descargar mi grabación</a>`;}catch(e){if($('#evidence-player'))$('#evidence-player').textContent=e.message;}}
  async function importAudio(file,id){if(!file)return;const owner=state;if(!C.examReady(state,id,D.lessons)){toast('Completa primero las clases del nivel.');return;}if(file.size>20*1024*1024||file.size<500||(!file.type.startsWith('audio/')&&!/\.(webm|mp3|wav|m4a|ogg|mp4)$/i.test(file.name))){toast('Elige un archivo de audio válido de hasta 20 MB.');return;}const url=URL.createObjectURL(file),audio=document.createElement('audio');audio.preload='metadata';audio.src=url;try{const duration=await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(Error('No se pudo leer la duración del audio. Prueba un archivo MP3, M4A o WAV.')),7000);audio.onloadedmetadata=()=>{clearTimeout(timeout);Number.isFinite(audio.duration)?resolve(audio.duration):reject(Error('El archivo no informa una duración finita. Graba aquí o conviértelo a WAV, MP3 o M4A.'));};audio.onerror=()=>{clearTimeout(timeout);reject(Error('El navegador no puede abrir ese formato de audio.'));};});if(duration<D.levels[id-1].record||duration>300)throw Error('La toma debe durar entre '+D.levels[id-1].record+' y 300 segundos.');if(state!==owner)throw Error('El recorrido cambió durante la importación. Vuelve a aportar el audio en su voz.');const mime=file.type||({mp3:'audio/mpeg',wav:'audio/wav',m4a:'audio/mp4',mp4:'audio/mp4',ogg:'audio/ogg',webm:'audio/webm'})[file.name.split('.').pop().toLowerCase()]||'audio/webm';await storeEvidence(id,file.type?file:new Blob([file],{type:mime}),duration);}catch(e){toast(e.message);}finally{URL.revokeObjectURL(url);audio.removeAttribute('src');audio.load();}}
  function askLoadPiece(index){ui.pendingPiece=repertoirePiece(index);if(state.composition?.bars.some(b=>b.melody.length)){modal(`<div class="eyebrow">UN NUEVO PUNTO DE PARTIDA</div><h2>¿Cargar este estudio?</h2><p>Reemplazará la composición del taller. Puedes descargar antes tu proyecto para conservarlo.</p><div class="btn-group mt-lg">${btn('Descargar proyecto actual','project-json','','secondary','download')}${btn('Cargar el estudio','load-piece','','','book')}</div>`);}else{state.composition=ui.pendingPiece;ui.pendingPiece=null;ui.bar=0;save();go('compose');}}
  function updateEditPreview(){const e=editSelection(),used=state.composition.bars[ui.bar].melody.reduce((a,n)=>a+n.d,0);if($('#edit-preview'))$('#edit-preview').textContent=C.noteName(e.m,e.spell==='flat')+' · '+(4-used)+' pulsos disponibles'+(e.m<state.settings.low||e.m>state.settings.high?' · fuera de tu zona cómoda':'');}
  async function handleAction(action,arg,el){
    switch(action){
      case'song-tab':A.stopSounds();ui.songTab=['lyrics','music','review'].includes(arg)?arg:'lyrics';render();break;
      case'lyric-section':ui.lyricSection=Object.hasOwn(C.SECTIONS,arg)?arg:'verse';ui.lyricAnalysis=false;render();break;
      case'lyric-analyse':ui.lyricAnalysis=true;render();break;
      case'prompt':ui.promptIndex=((ui.promptIndex||0)+1)%C.PROMPTS.length;render();break;
      case'feedback-remove':state.composition.feedback.splice(Number(arg),1);save();render();break;
      case'project-sheet':if(state.composition)download(C.leadSheet(state.composition),'verso-hoja-cancion.txt','text/plain;charset=utf-8');break;
      case'transpose':{const p=C.transposePiece(state.composition,Number(arg));A.stopSounds();state.composition=p;ui.editNote=Math.max(36,Math.min(84,(ui.editNote||state.settings.base)+Number(arg)));save();render();toast('Melodía, acordes y tonalidad transportados. Comprueba la zona antes de cantar.');break;}
      case'go':go(arg);break;
      case'menu':$('#sidebar').classList.toggle('open');break;
      case'close':closeModal();render();break;
      case'method':go('method');break;
      case'method-full':closeModal();go('method');break;
      case'mic-help':modal(`<div class="eyebrow">AYUDA CON EL MICRÓFONO</div><h2>Una lectura que puedas escuchar.</h2><ol class="step-list"><li>Abre HTTPS en una pestaña normal y permite el micrófono.</li><li>Silencia altavoces y otras fuentes. El control apaga sus referencias.</li><li>Confirma referencia y límites cómodos en Ajustes. No persigas una nota que queda fuera.</li><li>Canta una nota recta, separa las repetidas y descansa. Ruido, vibrato o armónicos pueden confundir la estimación.</li></ol><p>El análisis no diagnostica voz ni autentica origen. Importar una toma de portafolio no sustituye el control acústico.</p>`);break;
      case'settings':settings();break;
      case'start':if(!state.seenIntro)intro(Number(arg));else{ui.lessonTab='learn';go('lesson/'+arg);}break;
      case'intro-start':state.seenIntro=true;save();closeModal();ui.lessonTab='learn';go('lesson/'+arg);break;
      case'lesson':ui.lessonTab='learn';go('lesson/'+arg);break;
      case'level':go('route/'+arg);break;
      case'expand':ui.expanded=ui.expanded===Number(arg)?0:Number(arg);$('#route-levels').innerHTML=routeLevels();break;
      case'lesson-tab':stopAssessment();ui.lessonTab=arg;render();break;
      case'exam':ui.examTab='summary';go('exam/'+arg);break;
      case'exam-tab':stopAssessment();if(ui.recording)stopRecording();ui.examTab=arg;render();break;
      case'practice-tab':go('practice/'+arg);break;
      case'complete-lesson':{const id=Number(arg),l=D.lessons[id-1],r=lessonRecord(id);if(C.lessonDone(state,id)){go(id%6===0?'exam/'+l.level:'lesson/'+(id+1));break;}if(!C.unlocked(state,l,D.lessons)){toast('Completa la clase y el control anterior antes de avanzar.');break;}if(!C.lessonReady(r,l)){toast('Completa preguntas, secuencia vocal, ejercicio escrito y observaciones.');ui.lessonTab='evaluate';stopAssessment();render();break;}r.completedAt=new Date().toISOString();save();stopAssessment();render();toast('Clase completada. Tu siguiente paso ya está disponible.');break;}
      case'complete-exam':{const id=Number(arg),l=D.levels[id-1],e=examRecord(id);if(e.completedAt){go(id<8?'lesson/'+(id*6+1):'progress');break;}const req=C.examRequirements(state,l,D.lessons),missing=req.filter(x=>!x.ok);if(missing.length){toast('Aún falta: '+missing[0].label.toLowerCase()+'.');break;}const audio=await VersoMedia.get(e.evidence.id);if(!audio){toast('El audio no está en este dispositivo. Graba o aporta una toma para cerrar el nivel.');ui.examTab='portfolio';render();break;}e.completedAt=new Date().toISOString();save();stopAssessment();modal(`<div class="eyebrow">NIVEL 0${id} COMPLETADO</div><h2>Tu práctica<br>ya tiene un nuevo lugar.</h2><p>Has reunido los requisitos de ${E(l.name.toLowerCase())}. Guarda una copia de tu avance y conserva las observaciones para la siguiente etapa.</p><div class="note mt">Este resultado es un registro personal de aprendizaje y no una acreditación oficial.</div><div class="btn-group mt-lg">${btn('Descargar progreso','backup','','secondary','download')}${btn(id<8?'Continuar al siguiente nivel':'Ver mi recorrido','next-level',id,'','arrow')}</div>`);break;}
      case'next-level':closeModal();go(Number(arg)<8?'lesson/'+(Number(arg)*6+1):'progress');break;
      case'assessment':{const [kind,id]=arg.split(':');await beginAssessment(kind,Number(id));break;}
      case'tuner':await toggleTuner();break;
      case'metronome':await metronome();break;
      case'tempo':tempoChange(ui.tempo+Number(arg));break;
      case'note':await playNotes([{m:Number(arg),d:1}],60);break;
      case'play-sequence':{const [seq,t]=arg.split('|');await playNotes(seq.split(',').map(Number),Number(t));break;}
      case'stop-sound':A.stopSounds();ui.metro=false;toast('Reproducción detenida.');break;
      case'ear-play':if(!ui.ear){const intervals=[2,3,4,7,12];ui.ear={base:Math.max(48,Math.min(65,state.settings.base)),interval:intervals[Math.floor(Math.random()*intervals.length)]};ui.earResult=null;render();}await playNotes([{m:ui.ear.base,d:1},{m:ui.ear.base+ui.ear.interval,d:1}],64);break;
      case'ear-answer':if(ui.ear&&!ui.earResult){const correct=Number(arg)===ui.ear.interval;ui.earScore[1]++;if(correct)ui.earScore[0]++;ui.earResult={correct};render();}break;
      case'ear-next':ui.ear=null;ui.earResult=null;await handleAction('ear-play','',el);break;
      case'piece-play':await playPiece(repertoirePiece(Number(arg)));break;
      case'piece-score':{const p=REPERTOIRE[Number(arg)],seq=voiceSeq(p.pattern);modal(`<div class="eyebrow">SEMILLA ORIGINAL · NIVEL ${p.level}</div><h2>${E(p.title)}</h2><p>${E(p.description)}</p>${Array.from({length:Math.ceil(seq.length/8)},(_,i)=>`<div class="score-scroll mt">${C.scoreSvg(seq.slice(i*8,i*8+8),{width:660,title:p.title})}</div>`).join('')}<div class="btn-group mt">${btn('Escuchar','piece-play',arg,'secondary','play')}${btn('Crear mi versión','piece-copy',arg,'','pen')}</div>`);break;}
      case'piece-copy':askLoadPiece(Number(arg));break;
      case'load-piece':if(ui.pendingPiece){state.composition=ui.pendingPiece;ui.pendingPiece=null;ui.bar=0;save();closeModal();go('compose');}break;
      case'compose-example':askLoadPiece(3);break;
      
      case'bar':ui.bar=Number(arg);render();break;
      case'bar-add':if(state.composition.bars.length<32){state.composition.bars.push({melody:[],chord:'C',section:'chorus'});ui.bar=state.composition.bars.length-1;save();render();}break;
      case'bar-remove':{const p=state.composition;if(p.bars.length<=1)break;if(p.bars.at(-1).melody.length){modal(`<h2>¿Quitar el último compás?</h2><p>Contiene notas o silencios. Puedes guardar antes una copia.</p><div class="btn-group mt">${btn('Descargar proyecto','project-json','','secondary','download')}${btn('Quitar último','bar-remove-confirm','','danger','trash')}</div>`);}else{p.bars.pop();ui.bar=Math.min(ui.bar,p.bars.length-1);save();render();}break;}
      case'bar-remove-confirm':state.composition.bars.pop();ui.bar=Math.min(ui.bar,state.composition.bars.length-1);save();closeModal();render();break;
      case'event-add':{const n=editSelection(),events=state.composition.bars[ui.bar].melody,sum=events.reduce((a,e)=>a+e.d,0);if(sum+n.d>4){toast('Quedan '+(4-sum)+' pulsos; no cabe esa duración.');break;}if(arg!=='rest'&&!C.inRange(n.m)){toast('Elige una altura válida del editor.');break;}events.push(arg==='rest'?{m:null,d:n.d}:{m:n.m,d:n.d,...(n.spell==='flat'?{spell:'flat'}:{}),...(n.breath?{breath:true}:{}),...(n.lyric.trim()?{lyric:n.lyric.trim()}:{})});ui.editNote=n.m;ui.editDuration=n.d;ui.editBreath=n.breath;ui.editSpelling=n.spell;ui.editLyric='';save();render();break;}
      case'event-remove':state.composition.bars[ui.bar].melody.splice(Number(arg),1);save();render();break;
      case'edit-listen':{const n=editSelection();if(n.m===null)toast('Elige una altura válida.');else await playNotes([{m:n.m,d:1}],60);break;}
      case'compose-analyse':ui.analysis=true;render();break;
      case'compose-play':await playPiece(state.composition);break;
      case'compose-export':modal(`<div class="eyebrow">TU TRABAJO, CONTIGO</div><h2>Conserva y continúa.</h2><p>JSON conserva el proyecto editable. MusicXML incluye melodía vocal, cifrado, secciones y texto manual por nota. La hoja TXT reúne letra y mapa de compases. Los compases incompletos se rellenan con silencios al exportar notación.</p><div class="note mt">La exportación no es una revisión artística ni una grabación. Completa ligaduras, dinámica y alineación detallada en un editor compatible.</div><div class="btn-group mt-lg">${btn('Proyecto JSON','project-json','','secondary','download')}${btn('Partitura MusicXML','project-xml','','','download')}${btn('Hoja de canción TXT','project-sheet','','secondary','download')}</div>`);break;
      case'project-json':if(state.composition)download(JSON.stringify(state.composition,null,2),'verso-cancion.json');break;
      case'project-xml':if(state.composition){download(C.musicXML(state.composition),'verso-cancion.musicxml','application/vnd.recordare.musicxml+xml');toast('Partitura exportada. Comprueba su edición en un programa compatible.');}break;
      case'backup':backup();break;
      case'import-backup':$('#progress-import')?.click();break;case'import-project':$('#project-import')?.click();break;
      case'import-confirm':if(ui.pendingImport){if(ui.recording||ui.pendingMedia){toast('Espera a que termine de guardarse el audio.');break;}pauseTimer();leaveView();state=ui.pendingImport;ui.pendingImport=null;ui.timer.elapsed=0;ui.timer.logged=0;save();closeModal();render();toast('Progreso restaurado. Las grabaciones se aportan por separado.');}break;
      case'timer':toggleTimer();break;
      case'timer-finish':pauseTimer();ui.timer.elapsed=0;ui.timer.logged=0;render();toast('Sesión registrada. Añade una observación sobre tu práctica.');break;
      case'record':await startRecording(Number(arg));break;
      case'reset-ask':modal(`<div class="eyebrow">DATOS DE ESTE DISPOSITIVO</div><h2>¿Empezar de nuevo?</h2><p>Se borrarán el progreso, el diario, la composición y las grabaciones de Verso en este navegador. Descarga primero lo que quieras conservar.</p><div class="btn-group mt-lg">${btn('Descargar progreso','backup','','secondary','download')}${btn('Sí, borrar mis datos locales','reset-confirm','','danger','trash')}</div>`);break;
      case'reset-confirm':{if(ui.recording||ui.pendingMedia){toast('Espera a que termine de guardarse el audio.');break;}pauseTimer();leaveView();for(const e of Object.values(state.exams))if(e.evidence)await VersoMedia.remove(e.evidence.id);localStorage.removeItem('verso-canto-v1');state=C.fresh();ui.timer.elapsed=0;ui.timer.logged=0;ui.quizResults={};ui.examResults={};ui.analysis=false;save();closeModal();go('home');toast('Datos locales borrados. Tu ruta vuelve a empezar.');break;}
    }
  }
  document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button||button.disabled)return;handleAction(button.dataset.action,button.dataset.arg||'',button).catch(err=>{ui.busy=false;toast(err.message||'No se pudo completar la acción. Inténtalo de nuevo.');});});
  document.addEventListener('submit',async e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();if(!form.reportValidity())return;const fd=new FormData(form),type=form.dataset.form;try{
    if(type==='quiz'){const id=Number(form.dataset.id),kind=form.dataset.kind,l=kind==='lesson'?D.lessons[id-1]:null,open=l?C.unlocked(state,l,D.lessons):C.examReady(state,id,D.lessons);if(!open){toast('Completa los requisitos anteriores antes de evaluarte.');return;}const questions=kind==='lesson'?l.quiz:paper(id),answers=questions.map((_,i)=>Number(fd.get('q'+i)));let correct=0;questions.forEach((q,i)=>{if(q.answer===answers[i])correct++;});const score=kind==='lesson'?correct:Math.round(correct/questions.length*100);if(kind==='lesson'){ui.quizResults[id]={answers,score};lessonRecord(id).quiz=Math.max(lessonRecord(id).quiz||0,score);}else{ui.examResults[id]={answers,score};examRecord(id).theory=Math.max(examRecord(id).theory||0,score);}save();stopAssessment();render();toast(kind==='lesson'?score+'/3 correctas. '+(score===3?'Comprensión aprobada.':'Revisa las explicaciones y repite.'):'Resultado: '+score+'/100. '+(score>=80?'Teoría aprobada.':'Necesitas 80 para aprobar.'));}
    if(type==='review'){const id=Number(form.dataset.id);if(!C.examReady(state,id,D.lessons))return;examRecord(id).review={name:String(fd.get('reviewer')).trim(),feedback:String(fd.get('feedback')).trim(),scores:[0,1,2,3].map(i=>Number(fd.get('r'+i)))};save();render();toast(C.reviewPass(examRecord(id))?'Revisión docente guardada. Criterios cumplidos.':'Revisión guardada. Para aprobar necesitas 16/20 y cada criterio al menos en 3.');}
    if(type==='settings'){const base=Number(fd.get('base')),low=Number(fd.get('low')),high=Number(fd.get('high'));if(![base,low,high].every(Number.isInteger)||base<40||base>72||!C.inRange(low)||!C.inRange(high)||low>high||base<low||base>high)throw Error('Revisa la zona y la referencia: la nota de partida debe quedar entre los límites cómodos.');state.settings={goal:Math.max(5,Math.min(120,Math.round(Number(fd.get('goal'))))),a:Math.max(436,Math.min(444,Number(fd.get('a')))),base,low,high,confirmed:!!fd.get('confirmed')};save();closeModal();render();toast('Referencia guardada. Las pruebas se habilitan solo si el patrón cabe en la zona confirmada.');}
    if(type==='work'){const id=Number(form.dataset.id),l=D.lessons[id-1];if(!C.unlocked(state,l,D.lessons))return;const work=String(fd.get('work')||'').trim();if(work.length<l.assignment.min)throw Error('Desarrolla el ejercicio hasta el mínimo indicado.');lessonRecord(id).work=work.slice(0,5000);save();render();toast('Ejercicio guardado. Su calidad se revisa con escucha y docente.');}
    if(type==='listener'){if(!state.composition)return;if(state.composition.feedback.length>=30)throw Error('El proyecto admite hasta treinta observaciones.');const item=C.validateFeedback({alias:fd.get('alias'),clarity:Number(fd.get('clarity')),recall:fd.get('recall'),comment:fd.get('comment'),again:!!fd.get('again'),listened:!!fd.get('listened')});if(!item.listened)throw Error('Confirma que la persona escuchó y las respuestas son reales.');state.composition.feedback.push(item);save();render();toast('Observación guardada. Describe una muestra, no una predicción.');}
    if(type==='journal'){state.journal.push({date:new Date().toLocaleString('es-EC',{dateStyle:'medium',timeStyle:'short'}),text:String(fd.get('entry')).trim()});state.journal=state.journal.slice(-200);save();render();toast('Observación guardada.');}
    if(type==='manual-time'){const date=String(fd.get('date')),minutes=Number(fd.get('minutes'));if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||date>C.dateKey()||minutes<1||minutes>240||!Number.isFinite(minutes))throw Error('Revisa la fecha y los minutos de tu sesión.');state.practice[date]=Math.min(1440,(state.practice[date]||0)+minutes);save();render();toast('Sesión declarada registrada.');}
  }catch(err){toast(err.message||'No se pudo guardar el formulario.');}});
  document.addEventListener('input',e=>{const el=e.target;if(el.dataset.songField&&['hook','brief','revision','release'].includes(el.dataset.songField)){state.composition[el.dataset.songField]=el.value;save();}if(el.id==='song-lyrics'){state.composition.lyrics[el.dataset.section]=el.value.slice(0,6000);const st=C.lyricStats(el.value);$('#lyric-stats').textContent=st.lines+' líneas · '+st.words+' palabras';save();}if(el.id==='edit-lyric')ui.editLyric=el.value.slice(0,50);if(el.id==='lesson-search'){ui.search=el.value;$('#route-levels').innerHTML=routeLevels();}if(el.id==='tempo-range')tempoChange(Number(el.value));if(el.id==='piece-title'){state.composition.title=el.value.slice(0,100);save();}if(el.id==='piece-notes'){state.composition.notes=el.value.slice(0,5000);save();$('#piece-wordcount').textContent=el.value.trim().split(/\s+/).filter(Boolean).length+' palabras';}});
  document.addEventListener('change',async e=>{const el=e.target;try{
    if(el.dataset.change==='lesson-check'){const id=Number(el.dataset.id),i=Number(el.dataset.index);if(!C.unlocked(state,D.lessons[id-1],D.lessons))return;const r=lessonRecord(id);r.checks=r.checks||[false,false,false];r.checks[i]=el.checked;save();stopAssessment();render();}
    if(el.dataset.change==='self-review'){examRecord(Number(el.dataset.id)).selfReview=el.checked;save();render();}
    if(el.id==='beats-select'){ui.beats=Number(el.value);$('#beat-dots').innerHTML=Array.from({length:ui.beats},()=>'<i></i>').join('');if(ui.metro){A.stopSounds();ui.metro=false;await metronome();}}
    if(el.id==='timer-goal'){ui.timer.goal=Number(el.value);render();}
    if(el.id==='piece-key'){state.composition.key=el.value;save();}
    if(el.id==='piece-tempo'){state.composition.tempo=Math.max(40,Math.min(180,Number(el.value)||80));el.value=state.composition.tempo;save();}
    if(el.id==='edit-note'){ui.editNote=Number(el.value);updateEditPreview();}if(el.id==='edit-breath')ui.editBreath=el.checked;if(el.id==='edit-duration')ui.editDuration=Number(el.value);if(el.id==='edit-spell'){ui.editSpelling=el.value;updateEditPreview();}
    if(el.id==='bar-section'){state.composition.bars[ui.bar].section=el.value;save();render();}
    if(el.id==='bar-chord'){const symbol=el.value.trim();if(!C.chord(symbol)){el.value=state.composition.bars[ui.bar].chord;throw Error('Acorde no reconocido. Prueba C, Am, G7, Cmaj7, Fsus2 o Bdim.');}state.composition.bars[ui.bar].chord=symbol;save();render();}
    if(el.id==='playback-mode'){ui.playbackMode=el.value;A.stopSounds();}
    if(el.id==='audio-import')await importAudio(el.files[0],Number(el.dataset.level));
    if(el.id==='project-import'){const file=el.files[0];if(!file)return;if(file.size>1024*1024)throw Error('El proyecto debe ser un JSON de hasta 1 MB.');ui.pendingPiece=C.validatePiece(JSON.parse(await file.text()));modal(`<div class="eyebrow">IMPORTAR COMPOSICIÓN</div><h2>Recupera tu idea.</h2><p>El proyecto ${E(ui.pendingPiece.title)} contiene ${ui.pendingPiece.bars.length} compases. Reemplazará el proyecto actual del taller; puedes descargarlo antes.</p><div class="btn-group mt-lg">${btn('Descargar proyecto actual','project-json','','secondary','download')}${btn('Usar este proyecto','load-piece','','','upload')}</div>`);}if(el.id==='progress-import'){const file=el.files[0];if(!file)return;if(file.size>8*1024*1024)throw Error('La copia de progreso no debe superar 8 MB. El audio se importa por separado.');const value=JSON.parse(await file.text());ui.pendingImport=C.validateState(value);modal(`<div class="eyebrow">RESTAURAR PROGRESO</div><h2>¿Usar esta copia?</h2><p>Contiene ${Object.values(ui.pendingImport.lessons).filter(x=>x.completedAt).length} clases completadas. Reemplazará progreso, diario y composición actuales. Las grabaciones de este dispositivo no se borran, pero el archivo no incluye audio de otros dispositivos.</p><div class="btn-group mt-lg">${btn('Descargar mi progreso actual','backup','','secondary','download')}${btn('Restaurar esta copia','import-confirm','','','upload')}</div>`);}
  }catch(err){toast(err instanceof SyntaxError?'El archivo no contiene un JSON válido de Verso.':err.message);}});
  $('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){closeModal();render();}});
  $('#dialog').addEventListener('cancel',()=>{setTimeout(()=>render(),0);});
  document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#sidebar')?.classList.remove('open');});
  document.addEventListener('visibilitychange',()=>{if(document.hidden){pauseTimer();stopAssessment();A.stopSounds();ui.tuning=false;ui.metro=false;if(ui.recording)stopRecording();}else render();});
  window.addEventListener('pagehide',()=>{pauseTimer();stopAssessment();A.stopSounds();if(ui.recording)stopRecording();save();});
  window.addEventListener('hashchange',route);
  /* Interfaz de diagnóstico de funciones puras y renderizado para pruebas sin navegador. */
  if(window.VERSO_TEST)window.VersoTest={ui,getState:()=>state,setState:s=>{state=C.validateState(s);},render,handleAction,routePage,lessonPage,examPage,composePage,homePage,practicePage,progressPage,methodPage,repertoirePiece,beginAssessment,timerElapsed};
  route();
})();
